var e={"a-4c3f54":{slug:`a-4c3f54`,birthDeath:`1857.12.03 — 1924.08.03`,nationality:`波兰裔英国`,englishName:`JOSEPH CONRAD`,movement:[`现代主义`,`心理现实主义`],bio:[`生于沙俄治下的波兰贵族家庭，少年随商船出海，二十岁加入英国商船队，直到近四十岁才用英语写出第一部长篇小说《阿尔迈耶的愚蠢》。海上岁月构成他创作的核心素材。`,`《黑暗之心》《吉姆爷》以多层转述和时间错位写殖民扩张的道德空洞，英语并非其母语，他却重塑了英语散文的密度与节奏，被视为现代小说叙事的先驱。`,`晚期《诺斯特罗莫》《间谍》《在西方的注视下》由海上冒险转向政治、告密与背叛，笔调愈发沉郁，把帝国边缘的个人命运写成关于忠诚与幻灭的伦理勘察。`],controversies:[{tag:`殖民叙事争议`,content:`《黑暗之心》对非洲与非洲人的再现长期受到批评，阿契贝指其把非洲写成欧洲心理的对照背景，相关争论至今未息。`}],works:[{year:`1899`,title:`《黑暗之心》`,type:`中篇小说`,note:`刚果之行改写的殖民寓言`},{year:`1900`,title:`《吉姆爷》`,type:`长篇小说`,note:`荣誉与自我放逐的心理剖析`},{year:`1904`,title:`《诺斯特罗莫》`,type:`长篇小说`,note:`虚构南美共和国的政治史诗`},{year:`1907`,title:`《间谍》`,type:`长篇小说`,note:`伦敦无政府主义与炸弹阴谋`},{year:`1911`,title:`《在西方的注视下》`,type:`长篇小说`,note:`俄国背景下的告密与赎罪`}],position:`他把海上冒险小说提升为关于忠诚、背叛与帝国阴影的道德寓言，多层叙述与延迟揭示的手法，使其成为维多利亚传统与先锋实验之间的关键桥梁。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-9edc03":{slug:`a-9edc03`,birthDeath:`1871.07.10 — 1922.11.18`,nationality:`法国`,englishName:`MARCEL PROUST`,movement:[`现代主义`,`意识流`],bio:[`生于巴黎富裕的资产阶级家庭，自幼患哮喘，长期半隐居。早年出入贵族沙龙，写作《欢乐与时日》与未完成的长篇《让·桑德伊》，在社交观察中积累素材。`,`1909年起以记忆为轴构建七卷本《追忆似水年华》，用非自愿记忆、绵延时间与绵长复句取代传统情节，第一卷《在斯万家那边》一九一三年自费出版。`,`后六卷在病中陆续问世，《索多姆和戈摩尔》《女囚》《失踪的阿尔贝蒂娜》《重寻逝去的时光》把同性欲望、嫉妒与社会喜剧纳入同一时间结构，奠定意识流小说的典范。`],controversies:[],works:[{year:`1913`,title:`《在斯万家那边》`,type:`长篇小说`,note:`七卷本的开篇与记忆实验`},{year:`1919`,title:`《在少女们身旁》`,type:`长篇小说`,note:`获龚古尔奖的第二卷叙事`},{year:`1921`,title:`《盖尔芒特家那边》`,type:`长篇小说`,note:`贵族沙龙与阶层剖析叙事`},{year:`1922`,title:`《索多姆和戈摩尔》`,type:`长篇小说`,note:`欲望与偏见的群像书写`},{year:`1923`,title:`《女囚》`,type:`长篇小说`,note:`嫉妒心理的极限推演叙事`},{year:`1927`,title:`《重寻逝去的时光》`,type:`长篇小说`,note:`时间与艺术的最终启示`}],position:`他以记忆而非情节组织小说，把一部个人回忆写成关于时间、欲望与艺术救赎的总体作品，长句与内心独白此后成为现代小说的基本语法。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-70f375":{slug:`a-70f375`,birthDeath:`1882.02.02 — 1941.01.13`,nationality:`爱尔兰`,englishName:`JAMES JOYCE`,movement:[`现代主义`,`意识流`],bio:[`生于都柏林天主教家庭，耶稣会学校出身，后与宗教和故乡决裂，自我流放至巴黎、苏黎世、的里雅斯特，以教授语言和写作维生，这段经历塑造其流亡视角。`,`《都柏林人》以顿悟式的短篇写城市瘫痪，《一个青年艺术家的画像》转向内心成长叙事；《尤利西斯》把都柏林一天膨胀为神话与意识流的迷宫。`,`晚年《芬尼根的守灵夜》以多语混成、梦呓与循环结构把语言实验推向极端，几乎重新发明了英语小说的可能性，其语言边界至今仍被争论。`],controversies:[{tag:`淫秽审判`,content:`《尤利西斯》一九二一年因杂志连载在纽约被判淫秽而禁，一九三三年纽约法院撤销禁令，成为现代文学审查史上的标志性案件。`}],works:[{year:`1914`,title:`《都柏林人》`,type:`短篇小说集`,note:`城市瘫痪与顿悟式结尾`},{year:`1916`,title:`《一个青年艺术家的画像》`,type:`长篇小说`,note:`成长叙事与内心独白交织`},{year:`1922`,title:`《尤利西斯》`,type:`长篇小说`,note:`一日之内的神话与意识流`},{year:`1939`,title:`《芬尼根的守灵夜》`,type:`长篇小说`,note:`多语梦呓与循环历史叙事`}],position:`他是二十世纪小说形式革命的核心人物，以意识流、神话并行与语言变形把小说从情节艺术推向语言本身，其影响覆盖此后几乎所有实验性写作。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-b19180":{slug:`a-b19180`,birthDeath:`1882.01.25 — 1941.03.28`,nationality:`英国`,englishName:`VIRGINIA WOOLF`,movement:[`现代主义`,`意识流`,`女性写作`],bio:[`生于伦敦知识分子家庭，父亲是批评家莱斯利·斯蒂芬。家中藏书与兄长的影响使她未受正规大学教育，却成为布卢姆斯伯里圈子的核心成员。`,`《达洛维夫人》《到灯塔去》《海浪》以流动的内心独白捕捉日常瞬间，把时间、记忆与性别经验编织为诗性结构，弱化外部情节而强化感知。`,`她同时是重要的随笔作家与出版人，霍加斯出版社印行了《荒原》等作品；《一间自己的房间》《三个基尼》把女性创作的物质条件写入文学批评。`],controversies:[],works:[{year:`1915`,title:`《远航》`,type:`长篇小说`,note:`处女作与女性成长主题`},{year:`1925`,title:`《达洛维夫人》`,type:`长篇小说`,note:`一日之内并行两条意识`},{year:`1927`,title:`《到灯塔去》`,type:`长篇小说`,note:`家庭记忆与时间流逝叙事`},{year:`1928`,title:`《奥兰多》`,type:`长篇小说`,note:`跨性别与跨世纪的传记戏仿`},{year:`1929`,title:`《一间自己的房间》`,type:`随笔`,note:`女性写作的物质前提论述`},{year:`1931`,title:`《海浪》`,type:`长篇小说`,note:`六声部独白与生命循环`}],position:`她把小说从事件叙述转向意识与感知的纹理，以诗性节奏呈现日常瞬间，并在随笔中为女性写作争取空间，是现代主义与女性主义文学的双重坐标。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-4ee478":{slug:`a-4ee478`,birthDeath:`1885.09.11 — 1930.03.02`,nationality:`英国`,englishName:`D. H. LAWRENCE`,movement:[`现代主义`,`心理现实主义`],bio:[`生于诺丁汉郡矿工家庭，母亲的教育抱负与矿区环境构成其早期经验，《儿子与情人》即以自传性笔触写母子羁绊与工业社会的深层压抑。`,`《虹》《恋爱中的女人》把两性关系、工业文明与生命本能置于同一视野，以强烈的意象和节奏推进心理叙事，形成极具个人色彩的现代主义风格。`,`晚年旅行意大利、墨西哥，写作《查泰莱夫人的情人》与大量随笔、诗歌，主张以身体与自然对抗机械文明，长期因作品直白描写而遭查禁。`],controversies:[{tag:`作品查禁`,content:`《查泰莱夫人的情人》一九二八年私下印行后长期被禁，一九六〇年企鹅出版社因出版该书受审，最终获判无罪，成为英国审查制度转折点。`}],works:[{year:`1913`,title:`《儿子与情人》`,type:`长篇小说`,note:`矿工家庭与母子情感纠葛`},{year:`1915`,title:`《虹》`,type:`长篇小说`,note:`三代人的欲望与工业变迁`},{year:`1920`,title:`《恋爱中的女人》`,type:`长篇小说`,note:`两性关系与文明批判叙事`},{year:`1928`,title:`《查泰莱夫人的情人》`,type:`长篇小说`,note:`身体书写与阶级隔阂叙事`}],position:`他把心理现实主义推向身体与本能层面，以浓烈意象对抗工业文明，其性描写引发的审查争议反而扩大了现代文学关于表达自由的讨论边界。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-fb1f41":{slug:`a-fb1f41`,birthDeath:`1875.06.06 — 1955.08.12`,nationality:`德国`,englishName:`THOMAS MANN`,movement:[`现代主义`,`现实主义`],bio:[`生于吕贝克商人世家，家族衰落经验化为长篇处女作《布登勃洛克一家》，以编年体写资产阶级由盛转衰，一九〇一年出版即确立其地位。`,`《威尼斯之死》以中篇写艺术家与欲望的崩解；《魔山》把疗养院变成欧洲思想辩论的舞台，用对话、讽刺与象征结构呈现战前欧洲的精神危机。`,`流亡美国后写作《浮士德博士》，以作曲家与魔鬼的契约隐喻德国文化与纳粹灾难，晚期随笔持续介入冷战与德国问题，显示其介入公共议题的姿态。`],controversies:[{tag:`政治立场分歧`,content:`一战期间发表《一个非政治者的观察》为德国文化辩护，与兄长海因里希·曼的民主立场公开冲突，后转向支持魏玛共和国并流亡反纳粹。`}],works:[{year:`1901`,title:`《布登勃洛克一家》`,type:`长篇小说`,note:`商人世家四代衰亡编年`},{year:`1912`,title:`《威尼斯之死》`,type:`中篇小说`,note:`艺术家欲望与秩序崩解`},{year:`1924`,title:`《魔山》`,type:`长篇小说`,note:`疗养院中的欧洲思想辩论`},{year:`1947`,title:`《浮士德博士》`,type:`长篇小说`,note:`以音乐契约隐喻德国灾难`}],position:`他继承十九世纪现实主义的长篇格局，又以其反讽与思想密度回应现代主义，把德国市民传统、艺术家困境与政治灾难写成一部连续的欧洲精神史。`,positionSource:`— 《西方正典》`,nobelYear:1929},"a-d83376":{slug:`a-d83376`,birthDeath:`1877.07.02 — 1962.08.09`,nationality:`德裔瑞士`,englishName:`HERMANN HESSE`,movement:[`现代主义`,`成长小说`],bio:[`生于德国施瓦本地区传教士家庭，少年期反抗神学院教育，做过学徒与书商。早期《彼得·卡门青》以乡土抒情确立作家声誉，此后专事写作。`,`《德米安》《悉达多》《荒原狼》转向内心探索，把印度哲学、荣格心理学与欧洲个体危机熔于一炉，写自我分裂、精神导师与通往整体的道路。`,`晚期《玻璃球游戏》以未来乌托邦构想知识精英的秩序与危机，获诺贝尔奖后作品在六十年代反文化运动中被重新发现，影响延续至今。`],controversies:[{tag:`战争立场争议`,content:`一战爆发后发表反民族主义文章《啊，朋友，不必用这种调子》，遭德国舆论围攻，被指背叛祖国，此后移居瑞士并入籍。`}],works:[{year:`1904`,title:`《彼得·卡门青》`,type:`长篇小说`,note:`乡土抒情与艺术家成长`},{year:`1919`,title:`《德米安》`,type:`长篇小说`,note:`自我分裂与精神引路人`},{year:`1922`,title:`《悉达多》`,type:`中篇小说`,note:`印度求道与自我合一叙事`},{year:`1927`,title:`《荒原狼》`,type:`长篇小说`,note:`市民性与狼性的人格分裂`},{year:`1943`,title:`《玻璃球游戏》`,type:`长篇小说`,note:`未来知识共和国的寓言`}],position:`他把成长小说改造成精神史寓言，以东方哲学与深度心理学拓展德语小说的内向维度，其个体救赎主题在战后青年文化中获得跨代际的共鸣。`,positionSource:`— 《西方正典》`,nobelYear:1946},"a-9ed76c":{slug:`a-9ed76c`,birthDeath:`1883.07.03 — 1924.06.03`,nationality:`奥匈帝国捷克裔`,englishName:`FRANZ KAFKA`,movement:[`现代主义`,`表现主义`,`荒诞文学`],bio:[`生于布拉格讲德语的犹太家庭，法学博士，白天在保险公司任职，业余写作。身份的多重边缘性，使他笔下的人物总处于被机构审判与排斥的位置。`,`《判决》《变形记》《在流放地》《饥饿艺术家》以精确冷静的笔法写荒诞处境，日常细节与超现实事件并置，形成后来被称为卡夫卡式的叙事。`,`长篇小说《审判》《城堡》《美国》均未完成，由挚友布罗德整理出版；他生前要求焚毁遗稿，却因此留下二十世纪最具影响力的未完成作品。`],controversies:[{tag:`遗稿出版争议`,content:`卡夫卡遗嘱要求布罗德焚毁全部未刊稿，布罗德违背遗愿整理出版《审判》《城堡》，此举被视为成就其文学地位的关键，也长期引发伦理争论。`}],works:[{year:`1913`,title:`《判决》`,type:`短篇小说`,note:`父子冲突与自我毁灭叙事`},{year:`1915`,title:`《变形记》`,type:`中篇小说`,note:`人变为虫的荒诞寓言故事`},{year:`1919`,title:`《在流放地》`,type:`短篇小说`,note:`刑罚机器与权力仪式叙事`},{year:`1925`,title:`《审判》`,type:`长篇小说`,note:`无名罪责与官僚迷宫叙事`},{year:`1926`,title:`《城堡》`,type:`长篇小说`,note:`永远无法抵达的权威叙事`}],position:`他以冷静的公文式语言写不可解释的处境，把现代官僚、家庭与宗教权威转化为普遍的荒诞经验，卡夫卡式已成为描述现代异化的通用词。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-a57142":{slug:`a-a57142`,birthDeath:`1880.11.06 — 1942.04.15`,nationality:`奥地利`,englishName:`ROBERT MUSIL`,movement:[`现代主义`,`思想小说`],bio:[`生于克拉根福的工程师家庭，先后受工程技术、心理学与哲学训练，博士论文研究马赫。早期《学生托乐斯的困惑》以寄宿学校写暴力、性觉醒与道德麻木。`,`《没有个性的人》自一九三〇年起分卷出版，以乌尔里希参与平行行动为线索，用随笔体章节穿插数学、神秘主义与奥匈帝国解体的诊断，全书未完成。`,`纳粹上台后流亡苏黎世、日内瓦，在贫病中反复修改遗稿，生前读者寥寥，战后被追认为与普鲁斯特、乔伊斯并列的现代思想小说代表。`],controversies:[],works:[{year:`1906`,title:`《学生托乐斯的困惑》`,type:`长篇小说`,note:`寄宿学校的暴力与道德麻木`},{year:`1921`,title:`《女醉汉》`,type:`戏剧`,note:`早期剧作与性别讽刺剧作`},{year:`1930`,title:`《没有个性的人》`,type:`长篇小说`,note:`平行行动与帝国解体叙事`},{year:`1933`,title:`《没有个性的人》第二卷`,type:`长篇小说`,note:`兄妹伦理与神秘主义叙事`},{year:`1943`,title:`《没有个性的人》遗稿`,type:`长篇小说`,note:`未完成的终章与开放结局`}],position:`他把小说写成思想实验，以精确的分析语言和开放的随笔结构处理价值崩塌时代的欧洲精神，其未完成巨著成为现代主义思想小说的极限样本。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-59b043":{slug:`a-59b043`,birthDeath:`1886.11.01 — 1951.05.30`,nationality:`奥地利`,englishName:`HERMANN BROCH`,movement:[`现代主义`,`思想小说`],bio:[`生于维也纳纺织工业家家庭，早年经营家族工厂，后转向数学、哲学与文学。四十五岁出版《梦游者》三部曲，以三个时代写欧洲价值体系的解体。`,`流亡美国后完成《维吉尔之死》，以诗人临终的内心独白融合抒情散文、诗歌与哲学思辨，探讨艺术在暴力时代是否仍有存在的理由，成为战后德语文学的核心文本。`,`晚期写作《无罪者》《诱惑者》并研究群众心理，生前未获广泛读者，却被视为与穆齐尔并肩的德语现代主义思想小说家，其影响在战后逐渐显现。`],controversies:[],works:[{year:`1931`,title:`《梦游者》`,type:`长篇小说`,note:`三部曲写价值体系的解体`},{year:`1945`,title:`《维吉尔之死》`,type:`长篇小说`,note:`临终独白与艺术之辩叙事`},{year:`1950`,title:`《无罪者》`,type:`长篇小说`,note:`十一篇故事组成的伦理探询`},{year:`1953`,title:`《诱惑者》`,type:`长篇小说`,note:`遗稿写群众蛊惑与顺从`}],position:`他以数学式的结构与音乐式的复调写欧洲精神的崩解，把小说推向哲学思辨的边缘，其关于艺术与暴力的追问在战后德语文学中影响深远。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-107396":{slug:`a-107396`,birthDeath:`1875.12.04 — 1926.12.29`,nationality:`奥地利`,englishName:`RAINER MARIA RILKE`,movement:[`现代主义`,`象征主义`],bio:[`生于布拉格德语区，早年习画、写诗，辗转慕尼黑、柏林与巴黎，曾任罗丹的秘书。与雕塑和视觉艺术的接触，促使他转向对外物的精确凝视。`,`《新诗集》以物诗著称，把豹、喷泉、古代雕像写成独立自足的存在；《马尔特·劳里茨·布里格手记》则以都市孤独者的笔记开创现代德语小说。`,`晚年隐居瑞士穆佐城堡，在极度孤独中完成《杜伊诺哀歌》与《致奥尔弗斯的十四行诗》，把天使、死亡与歌唱凝为二十世纪德语诗歌的高峰。`],controversies:[],works:[{year:`1905`,title:`《祈祷书》`,type:`诗集`,note:`早期祈祷体与漂泊主题`},{year:`1907`,title:`《新诗集》`,type:`诗集`,note:`物诗与精确凝视的诗学`},{year:`1910`,title:`《马尔特手记》`,type:`长篇小说`,note:`都市孤独者的笔记体叙事`},{year:`1923`,title:`《杜伊诺哀歌》`,type:`诗集`,note:`天使、死亡与存在之问`},{year:`1923`,title:`《致奥尔弗斯的十四行诗》`,type:`诗集`,note:`歌唱与消逝的循环主题`}],position:`他把象征主义推向存在论层面，以物诗和哀歌重建人与世界的关系，其语言密度与音乐性使德语现代诗歌获得新的精神高度。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-41a247":{slug:`a-41a247`,birthDeath:`1865.06.13 — 1939.01.28`,nationality:`爱尔兰`,englishName:`WILLIAM BUTLER YEATS`,movement:[`现代主义`,`象征主义`,`爱尔兰文艺复兴`],bio:[`生于都柏林画家家庭，童年在斯莱戈乡间度过，爱尔兰民间传说与神秘学成为其诗歌的底色。早期作品承袭浪漫主义与凯尔特复兴的梦幻风格。`,`与格里高利夫人等创立阿贝剧院，写作《凯瑟琳女伯爵》等诗剧；《责任》之后诗风转向冷硬具体，把公共事件与私人经验锻入紧缩的象征结构。`,`晚年以《塔》《盘旋的楼梯》写衰老、肉体与历史的螺旋循环，并形成以月相为核心的神秘哲学体系《幻象》，完成了从唯美诗人到现代诗人的转变。`],controversies:[],works:[{year:`1889`,title:`《乌辛的漫游》`,type:`长诗`,note:`凯尔特神话与早期象征`},{year:`1892`,title:`《凯瑟琳女伯爵》`,type:`诗剧`,note:`民族传说与舞台实践剧作`},{year:`1925`,title:`《幻象》`,type:`散文`,note:`月相与历史螺旋的体系`},{year:`1928`,title:`《塔》`,type:`诗集`,note:`衰老、历史与驶向拜占庭`},{year:`1933`,title:`《盘旋的楼梯》`,type:`诗集`,note:`晚期肉身与欲望的颂歌`}],position:`他把爱尔兰神话与象征主义转换为现代诗歌的语言，以历史循环与肉体悖论处理个人与民族命运，是英语现代诗从唯美主义转向现代主义的关键人物。`,positionSource:`— 《西方正典》`,nobelYear:1923},"a-e09bd2":{slug:`a-e09bd2`,birthDeath:`1888.09.26 — 1965.01.04`,nationality:`美国裔英国`,englishName:`T. S. ELIOT`,movement:[`现代主义`,`象征主义`],bio:[`生于美国圣路易斯，哈佛求学后赴牛津，一九二七年入英国籍并皈依圣公会。早期诗作以都市衰败与心理疲惫著称，受法国象征派与但丁影响。`,`《荒原》以碎片拼贴、多语引用与神话框架写战后欧洲的精神荒芜，经庞德删改后成为现代主义诗歌的宣言式作品，重塑英语诗歌的句法与引喻方式。`,`后期转向宗教与戏剧，《四个四重奏》以时间与永恒为主题，语言趋于澄明；同时以批评文章确立新批评的经典谱系，影响延续数十年。`],controversies:[{tag:`反犹书写争议`,content:`其早期诗歌与书信中夹杂反犹措辞，二十世纪后期被研究者系统揭示，引发关于如何评价经典作家私人偏见与作品关系的持续争论。`}],works:[{year:`1917`,title:`《普鲁弗洛克及其他观察》`,type:`诗集`,note:`都市焦虑与戏剧性独白`},{year:`1922`,title:`《荒原》`,type:`长诗`,note:`碎片拼贴与战后精神荒芜`},{year:`1925`,title:`《空心人》`,type:`长诗`,note:`信仰崩塌后的虚无图景`},{year:`1935`,title:`《大教堂凶杀案》`,type:`诗剧`,note:`殉道主题与宗教戏剧剧作`},{year:`1943`,title:`《四个四重奏》`,type:`长诗`,note:`时间、历史与永恒之思`}],position:`他以引喻密集的碎片结构重写现代诗歌，把神话、宗教与都市经验并置，同时通过批评实践塑造了现代主义经典的标准，影响远超诗歌本身。`,positionSource:`— 《西方正典》`,nobelYear:1948},"a-755881":{slug:`a-755881`,birthDeath:`1885.10.30 — 1972.11.01`,nationality:`美国`,englishName:`EZRA POUND`,movement:[`现代主义`,`意象派`],bio:[`生于爱达荷，求学宾夕法尼亚与汉密尔顿，一九〇八年赴欧洲，先后活动于伦敦、巴黎、拉帕洛。以编辑与评论推动意象派与漩涡主义，深刻影响同代诗人。`,`《休·赛尔温·莫伯利》以反讽与拼贴写现代文化的失败；长篇《诗章》自一九一五年起持续半个世纪，混合历史文献、经济学与多语引文，结构开放。`,`二战期间在罗马电台发表亲法西斯广播，战后因叛国罪受审，以精神失常免于死刑，长期关押于精神病院，晚期沉默，其诗学遗产与政治污点始终并置。`],controversies:[{tag:`叛国与反犹广播`,content:`二战期间在罗马电台发表攻击美国与犹太人的广播，一九四五年被捕并因叛国罪受审，最终以精神失常为由免刑，文学界对其评价长期分裂。`}],works:[{year:`1908`,title:`《熄灭的灯火》`,type:`诗集`,note:`早期抒情与普罗旺斯影响`},{year:`1912`,title:`《回击》`,type:`诗集`,note:`意象派诗学的集中呈现`},{year:`1920`,title:`《休·赛尔温·莫伯利》`,type:`长诗`,note:`现代文化失败的讽刺拼贴`},{year:`1934`,title:`《阅读ABC》`,type:`批评`,note:`诗学与阅读方法入门论述`},{year:`1969`,title:`《诗章》`,type:`长诗`,note:`跨半个世纪的历史拼贴`}],position:`他是现代主义诗歌运动的组织者与理论家，以意象派主张和编辑实践改变了英语诗歌的趣味，但其政治选择使这份遗产始终伴随尖锐的道德争议。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-a6725e":{slug:`a-a6725e`,birthDeath:`1874.02.03 — 1946.07.27`,nationality:`美国`,englishName:`GERTRUDE STEIN`,movement:[`现代主义`,`语言实验`],bio:[`生于宾夕法尼亚犹太家庭，在维也纳、巴黎长大，曾入约翰斯·霍普金斯医学院。一九〇三年定居巴黎，与兄长利奥收藏先锋绘画，形成著名的周六沙龙。`,`《三个女人》以重复、回旋的句法写女性心理；《温柔的纽扣》以文字游戏写同性情感；她试图用语言对应立体主义的共时视角，淡化情节与指称。`,`《美国人的成长》以实验传记写家族史，《爱丽丝·B·托克拉斯自传》则以通俗口吻获得大众读者，其沙龙扶植了海明威、菲茨杰拉德等一代作家。`],controversies:[],works:[{year:`1909`,title:`《三个女人》`,type:`中篇小说`,note:`重复句法与女性心理叙事`},{year:`1914`,title:`《温柔的纽扣》`,type:`短篇作品`,note:`文字游戏与同性情感叙事`},{year:`1925`,title:`《美国人的成长》`,type:`长篇散文`,note:`实验传记与家族史思辨`},{year:`1933`,title:`《爱丽丝·B·托克拉斯自传》`,type:`回忆录`,note:`沙龙生活与通俗叙述论述`}],position:`她以语言的重复与去指称化回应立体主义，把散文变成声音与节奏的实验，其巴黎沙龙则成为英语现代主义生成的重要现场。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-7ce612":{slug:`a-7ce612`,birthDeath:`1879.10.02 — 1955.08.07`,nationality:`美国`,englishName:`WALLACE STEVENS`,movement:[`现代主义`,`哲学诗`],bio:[`生于宾夕法尼亚，哈佛毕业后入纽约法学院，长期在康涅狄格一家保险公司任职至副总裁。商务生涯与诗歌写作并行，直到晚年才获得广泛承认。`,`《簧风琴》以感官的华丽与想象力的颂扬震动诗坛；《弹蓝色吉他的人》以组诗反复追问想象与现实的关系，把诗歌本身变成哲学性的沉思对象。`,`晚期《运往夏天》《秋天的极光》《岩石》语言趋于简净，围绕死亡、秩序与虚构的救赎展开，形成二十世纪美国最完整的形而上诗学之一。`],controversies:[],works:[{year:`1923`,title:`《簧风琴》`,type:`诗集`,note:`感官想象与异教式颂歌`},{year:`1937`,title:`《弹蓝色吉他的人》`,type:`组诗`,note:`想象与现实的往复辩证`},{year:`1947`,title:`《运往夏天》`,type:`诗集`,note:`晚期风格与死亡沉思诗篇`},{year:`1950`,title:`《秋天的极光》`,type:`诗集`,note:`衰老、虚无与虚构秩序`},{year:`1954`,title:`《岩石》`,type:`诗集`,note:`终篇的澄明与告别之诗`}],position:`他把诗歌写成关于想象如何构造现实的哲学，以华美而精确的语言守护世俗世界，是美国现代主义中最具思辨气质的抒情诗人。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-6808a1":{slug:`a-6808a1`,birthDeath:`1874.03.26 — 1963.01.29`,nationality:`美国`,englishName:`ROBERT FROST`,movement:[`现代主义`,`新英格兰诗歌`],bio:[`生于旧金山，父亲早逝后随母亲迁回新英格兰，做过农活、教书与工厂工。一九一二年携家赴英国，在庞德与爱德华·托马斯的鼓励下出版成名作。`,`《男孩的意志》《波士顿以北》以新英格兰乡野为背景，用口语化韵律与戏剧性独白写日常劳作背后的孤独、恐惧与道德困境，表面朴素而内里幽暗。`,`《新罕布什尔》《小河西流》《见证树》持续拓展田园与哲思的张力，四次获普利策奖，晚年成为美国公共生活中最受尊敬的诗人，其公共形象与诗名并重。`],controversies:[],works:[{year:`1913`,title:`《男孩的意志》`,type:`诗集`,note:`新英格兰乡野与独白诗篇`},{year:`1914`,title:`《波士顿以北》`,type:`诗集`,note:`对话体叙事与道德困境`},{year:`1923`,title:`《新罕布什尔》`,type:`诗集`,note:`成名后的抒情与沉思诗篇`},{year:`1928`,title:`《小河西流》`,type:`诗集`,note:`自然意象与时间之流诗篇`},{year:`1942`,title:`《见证树》`,type:`诗集`,note:`晚期黑暗与信仰之问诗篇`}],position:`他用看似传统的格律容纳现代的心理不安，把地方经验写成普遍寓言，其口语与格律的平衡为现代英语诗歌保留了叙事与声音的维度。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-f32841":{slug:`a-f32841`,birthDeath:`1883.09.17 — 1963.03.04`,nationality:`美国`,englishName:`WILLIAM CARLOS WILLIAMS`,movement:[`现代主义`,`意象派`,`美国本土诗`],bio:[`生于新泽西州卢瑟福，宾夕法尼亚大学医学博士，一生在故乡行医并接生数千名婴儿。行医与写诗并行，使他坚持从具体、可触的本地经验出发。`,`早期受意象派影响，《春天及一切》以短句、断行与日常物件捕捉瞬间感知；他反对艾略特的学院化与欧洲中心，主张用美国口语建立本土诗学。`,`长篇《斐特森》以一座城市为主人公，混合书信、散文与抒情片段；晚期《沙漠音乐》《来自布鲁盖尔的画》形式更自由，影响自垮掉派至语言诗。`],controversies:[],works:[{year:`1923`,title:`《春天及一切》`,type:`诗集`,note:`红色手推车式的瞬间感知`},{year:`1925`,title:`《美国性情》`,type:`诗集`,note:`本土语言与历史反省主题`},{year:`1946`,title:`《斐特森》`,type:`长诗`,note:`以城市为主人公的史诗`},{year:`1954`,title:`《沙漠音乐》`,type:`诗集`,note:`晚期自由节奏与感官书写`}],position:`他坚持美国口语与本地经验，用意象的精确对抗抽象传统，其长诗把城市生活写成史诗，为战后美国诗歌开辟了非学院化的道路。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-f53a35":{slug:`a-f53a35`,birthDeath:`1888.10.16 — 1953.11.27`,nationality:`美国`,englishName:`EUGENE ONEILL`,movement:[`现代主义`,`表现主义戏剧`],bio:[`生于纽约演员家庭，幼年随剧团漂泊，曾航海、淘金、当记者。复杂家庭与底层经历成为其剧作的原始材料，也使他对人性的阴暗面保持直视。`,`一九一〇年代加入普罗温斯敦小剧场，以《琼斯皇帝》《毛猿》引入面具、鼓声与表现主义布景，把心理冲突外化为舞台视觉，突破美国商业戏剧的惯例。`,`晚期《送冰的人来了》《长夜漫漫路迢迢》转向自传与静默的悲剧，后者在身后首演，以一天之内的家庭独角戏写下美国戏剧最沉痛的纪念碑。`],controversies:[],works:[{year:`1920`,title:`《琼斯皇帝》`,type:`戏剧`,note:`鼓声与内心恐惧的外化`},{year:`1922`,title:`《毛猿》`,type:`戏剧`,note:`阶级与身份的表现主义`},{year:`1924`,title:`《榆树下的欲望》`,type:`戏剧`,note:`农庄家庭的情欲与占有`},{year:`1931`,title:`《哀悼》`,type:`戏剧`,note:`希腊悲剧的美国改写剧作`},{year:`1946`,title:`《送冰的人来了》`,type:`戏剧`,note:`酒馆群像与虚假希望剧作`},{year:`1956`,title:`《长夜漫漫路迢迢》`,type:`戏剧`,note:`自传性家庭悲剧的再现`}],position:`他把欧洲表现主义与希腊悲剧引入美国舞台，以家庭与底层的痛苦经验建立严肃戏剧传统，是美国现代戏剧真正的奠基者。`,positionSource:`— 《西方正典》`,nobelYear:1936},"a-cf5668":{slug:`a-cf5668`,birthDeath:`1898.02.10 — 1956.08.14`,nationality:`德国`,englishName:`BERTOLT BRECHT`,movement:[`现代主义`,`史诗剧场`],bio:[`生于奥格斯堡市民家庭，大学习医学，一战期间做过护理员。战后在慕尼黑与柏林投身戏剧，以《夜半鼓声》获克莱斯特奖，并逐渐形成激进的政治立场。`,`他与魏尔合作《三毛钱歌剧》获得商业成功，同时提出史诗剧场与间离效果，主张以中断、歌队与字幕阻止观众沉浸，迫使人们思考社会结构。`,`纳粹上台后流亡丹麦、瑞典、芬兰、美国，写下《大胆妈妈》《四川好人》《伽利略传》等主要剧作；战后定居东柏林，领导柏林剧团实践其剧场理论。`],controversies:[{tag:`政治审查与作证`,content:`一九四七年在美国众议院非美活动调查委员会作证，否认自己曾是共产党员，此事在流亡知识分子中引发争议，也影响其在美国的处境。`}],works:[{year:`1922`,title:`《夜半鼓声》`,type:`戏剧`,note:`战后归乡与革命讽刺剧作`},{year:`1928`,title:`《三毛钱歌剧》`,type:`戏剧`,note:`下层社会与资本逻辑剧作`},{year:`1939`,title:`《大胆妈妈和她的孩子们》`,type:`戏剧`,note:`战争生意与母亲形象剧作`},{year:`1943`,title:`《四川好人》`,type:`戏剧`,note:`善行与生存的两难寓言`},{year:`1943`,title:`《伽利略传》`,type:`戏剧`,note:`科学真理与权力妥协剧作`},{year:`1948`,title:`《高加索灰阑记》`,type:`戏剧`,note:`民间故事与阶级正义剧作`}],position:`他以间离效果和史诗剧场重新定义舞台与观众的关系，把戏剧变成社会分析与政治启蒙的工具，其理论与剧作深刻影响二十世纪世界戏剧。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-d5fe40":{slug:`a-d5fe40`,birthDeath:`1894.05.27 — 1961.07.01`,nationality:`法国`,englishName:`LOUIS-FERDINAND CELINE`,movement:[`现代主义`,`黑暗现实主义`],bio:[`生于巴黎近郊小商人家庭，一战中负伤，后赴非洲殖民地与美国底特律谋生，回国行医。《长夜行》以底层游历与口语脏话震动文坛，被视为法语散文的革命。`,`他以省略号、断裂句与街头俚语取代书面语法，把战争、殖民、工厂与医疗写成一场持续的恶心与怜悯，影响了此后法语小说的语言解放。`,`战后因战时通敌言论被判刑，流亡丹麦，后获赦返回法国，晚年以《从城堡到城堡》等三部曲继续以偏执而凌厉的笔触写欧洲文明的溃败。`],controversies:[{tag:`反犹与通敌`,content:`二战期间发表多篇反犹小册子并与占领当局往来，战后被控通敌，流亡丹麦后获赦。其文学成就与政治污点长期并存，评价始终分裂。`}],works:[{year:`1932`,title:`《长夜行》`,type:`长篇小说`,note:`口语体与底层漂泊长卷`},{year:`1936`,title:`《分期死亡》`,type:`长篇小说`,note:`童年与诊所的黑色喜剧`},{year:`1947`,title:`《伦敦桥》`,type:`长篇小说`,note:`战时伦敦的狂乱与虚无`},{year:`1957`,title:`《从城堡到城堡》`,type:`长篇小说`,note:`流亡德国与晚年偏执叙事`}],position:`他把法语小说从书面雅语推向口语的极端，以断裂节奏和黑色幽默写现代人的屈辱，其形式革新与政治污点共同构成二十世纪文学最棘手的遗产。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-70b07b":{slug:`a-70b07b`,birthDeath:`1869.11.22 — 1951.02.19`,nationality:`法国`,englishName:`ANDRE GIDE`,movement:[`现代主义`,`道德主义小说`],bio:[`生于巴黎清教家庭，早年受象征主义影响，参与《瓦勒里》圈子。一九〇二年《背德者》以欲望解放与道德自省引发争论，确立其精神探索者的形象。`,`《窄门》《田园交响曲》以克制叙事写信仰、禁欲与爱的冲突；《梵蒂冈的地窖》以讽刺与行动哲学提出无偿行为，结构上不断试验视角与反讽。`,`《伪币制造者》以多线人物与小说中的小说打破单一线索，是他唯一自称小说的作品；非洲旅行与《从苏联归来》则显示其公开介入政治与道德议题。`],controversies:[{tag:`苏联幻灭`,content:`一九三六年访问苏联后出版《从苏联归来》，直言观察到的专制与贫困，与法国左翼知识界决裂，成为二十世纪知识分子政治幻灭的标志性文本。`}],works:[{year:`1897`,title:`《地粮》`,type:`散文诗`,note:`感官解放与抒情箴言诗篇`},{year:`1902`,title:`《背德者》`,type:`长篇小说`,note:`欲望、疾病与道德自省`},{year:`1909`,title:`《窄门》`,type:`长篇小说`,note:`禁欲信仰与爱情牺牲叙事`},{year:`1914`,title:`《梵蒂冈的地窖》`,type:`长篇小说`,note:`讽刺冒险与无偿行为叙事`},{year:`1919`,title:`《田园交响曲》`,type:`中篇小说`,note:`盲女、信仰与自我欺骗`},{year:`1925`,title:`《伪币制造者》`,type:`长篇小说`,note:`多线叙事与小说中的小说`}],position:`他以道德实验与叙事实验并行，把欲望、信仰与自由写成不断自我质询的过程，其对小说视角的拆解为法国现代主义提供了关键的过渡形态。`,positionSource:`— 《西方正典》`,nobelYear:1947},"a-8dbd6e":{slug:`a-8dbd6e`,birthDeath:`1861.12.19 — 1928.09.13`,nationality:`意大利`,englishName:`ITALO SVEVO`,movement:[`现代主义`,`心理小说`],bio:[`生于奥匈帝国治下的的里雅斯特犹太商人家庭，学商后长期在银行与家族涂料公司任职。早期两部小说自费出版，未获关注，遂搁笔多年。`,`在乔伊斯与弗洛伊德影响下重拾写作，《泽诺的意识》以精神分析治疗为框架，让主人公以不可靠的回忆写戒烟、婚姻、商业与战争，充满反讽。`,`小说一九二三年出版后经乔伊斯与法国批评界推介获得声誉，他被视为意大利意识流与心理小说的先驱，其名望直到晚年才真正到来，堪称迟来的认可。`],controversies:[],works:[{year:`1892`,title:`《一生》`,type:`长篇小说`,note:`自费出版的写实处女作`},{year:`1898`,title:`《衰老》`,type:`长篇小说`,note:`婚姻失败与中年危机叙事`},{year:`1923`,title:`《泽诺的意识》`,type:`长篇小说`,note:`精神分析框架下的不可靠叙事`}],position:`他把精神分析的不可靠叙述引入意大利小说，以反讽瓦解主人公的自我辩护，使的里雅斯特的边缘经验进入欧洲现代主义的核心谱系。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-59e345":{slug:`a-59e345`,birthDeath:`1867.06.28 — 1936.12.10`,nationality:`意大利`,englishName:`LUIGI PIRANDELLO`,movement:[`现代主义`,`荒诞戏剧`],bio:[`生于西西里硫磺矿主家庭，波恩大学语言学博士，早年写诗与短篇。家族矿场崩溃与妻子长期精神疾病，使他持续关注身份的不稳定与现实的相对性。`,`《已故的帕斯卡尔》以身份错认与假死写自我之虚无；《六个寻找作者的剧中人》《亨利四世》把排练、面具与疯狂搬上舞台，创造戏中戏的现代范式。`,`一九二〇年代他组织剧团巡演欧洲，戏剧声名超过小说；晚期《今晚我们即兴演出》进一步拆解舞台幻觉，其作品成为荒诞派戏剧的直接先声。`],controversies:[{tag:`法西斯党籍`,content:`一九二四年加入法西斯党，并曾公开支持墨索里尼，后期与政权关系渐疏。这一政治选择长期是评价其生平时的争议点。`}],works:[{year:`1904`,title:`《已故的帕斯卡尔》`,type:`长篇小说`,note:`假死与身份虚无的寓言`},{year:`1921`,title:`《六个寻找作者的剧中人》`,type:`戏剧`,note:`戏中戏与作者权威瓦解`},{year:`1922`,title:`《亨利四世》`,type:`戏剧`,note:`面具、疯狂与自我选择`},{year:`1930`,title:`《今晚我们即兴演出》`,type:`戏剧`,note:`舞台幻觉的进一步拆解`}],position:`他以戏中戏和身份错认揭示自我的碎片化，把剧场变成关于真实与虚构的哲学实验，为现代戏剧提供了从自然主义走向荒诞的关键环节。`,positionSource:`— 《西方正典》`,nobelYear:1934},"a-ad3484":{slug:`a-ad3484`,birthDeath:`1896.10.12 — 1981.09.12`,nationality:`意大利`,englishName:`EUGENIO MONTALE`,movement:[`现代主义`,`隐逸派`],bio:[`生于热那亚商人家庭，因健康原因未完成大学学业，自学音乐、哲学与文学。早年受象征派与邓南遮影响，后在利古里亚海岸的荒芜景物中找到自己的声音。`,`《乌贼骨》以干枯的岩石、海风与废瓶写存在的破碎，提出非确定性与恶之诗学；《境遇》《暴风雨及其他》继续以艰涩意象回应战争与历史的重压。`,`移居米兰后从事新闻、翻译与音乐评论，译介叶芝、艾略特与莎士比亚；晚期《萨图拉》转向日常与丧妻之痛，语言趋于简净而低回深沉。`],controversies:[],works:[{year:`1925`,title:`《乌贼骨》`,type:`诗集`,note:`利古里亚海景与存在破碎`},{year:`1939`,title:`《境遇》`,type:`诗集`,note:`晦涩意象与时代阴影诗篇`},{year:`1956`,title:`《暴风雨及其他》`,type:`诗集`,note:`历史暴力与诗歌形式难度`},{year:`1971`,title:`《萨图拉》`,type:`诗集`,note:`日常、衰老与丧妻之痛`}],position:`他把象征主义的晦涩与战后意大利的历史经验结合，以极少而坚硬的意象写存在的虚无，其诗学深刻塑造了二十世纪意大利诗歌的语言标准。`,positionSource:`— 《西方正典》`,nobelYear:1975},"a-75285b":{slug:`a-75285b`,birthDeath:`1898.06.05 — 1936.08.19`,nationality:`西班牙`,englishName:`FEDERICO GARCIA LORCA`,movement:[`现代主义`,`西班牙民谣诗`],bio:[`生于格拉纳达的富裕农家，幼年学钢琴，后转文学。与达利、布努埃尔交好，深浸安达卢西亚吉普赛民谣与深歌传统，形成音乐性极强的诗歌语言。`,`《吉普赛谣曲》以谣曲体和重复副歌写欲望、死亡与命运，成为西班牙语世界最广为传诵的诗集；《诗人在纽约》则在旅美经验中转向超现实与城市抗议。`,`戏剧方面以《血婚》《叶尔玛》《贝尔纳达·阿尔瓦之家》写乡村女性的压抑与反抗，形成农村悲剧三部曲；内战爆发后遭长枪党枪杀，遗体至今未寻获。`],controversies:[],works:[{year:`1928`,title:`《吉普赛谣曲》`,type:`诗集`,note:`谣曲体与安达卢西亚命运`},{year:`1933`,title:`《血婚》`,type:`戏剧`,note:`乡村婚礼与私奔悲剧剧作`},{year:`1934`,title:`《叶尔玛》`,type:`戏剧`,note:`不孕与女性压抑的悲剧`},{year:`1936`,title:`《贝尔纳达·阿尔瓦之家》`,type:`戏剧`,note:`丧夫之家与女儿禁锢剧作`},{year:`1940`,title:`《诗人在纽约》`,type:`诗集`,note:`城市异化与超现实抗议`}],position:`他把民间谣曲、深歌与超现实主义熔为一体，使西班牙语诗歌重获声音与身体性，其戏剧则把乡村女性的沉默写成具有普遍力量的悲剧。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-fb192b":{slug:`a-fb192b`,birthDeath:`1864.09.29 — 1936.12.31`,nationality:`西班牙`,englishName:`MIGUEL DE UNAMUNO`,movement:[`存在主义`,`九八一代`],bio:[`生于巴斯克地区毕尔巴鄂，历任萨拉曼卡大学希腊语教授与校长，是九八一代的核心人物。他兼写诗、小说、随笔与哲学，长期介入西班牙公共生活。`,`《生命的悲剧意识》以信仰与理性的冲突为中心，提出个人不朽的渴望；《雾》以对话与内心独白写爱与自我的不可知，并自创尼沃拉一词对抗现实主义小说。`,`《圣曼努埃尔·布埃诺，殉道者》以乡村神父的自我怀疑写信仰的悖论；内战初期因公开斥责法西斯将领被免职并软禁，年底死于家中。`],controversies:[{tag:`政治立场反复`,content:`早年支持共和、后一度对佛朗哥政权抱有期待，最终公开斥责其暴力而遭软禁，其政治表态的反复长期为评论者争论。`}],works:[{year:`1905`,title:`《堂吉诃德与桑丘的生活》`,type:`随笔`,note:`以小说人物论西班牙精神`},{year:`1913`,title:`《生命的悲剧意识》`,type:`哲学随笔`,note:`信仰、理性与不朽之渴`},{year:`1914`,title:`《雾》`,type:`长篇小说`,note:`对话体与自我不可知叙事`},{year:`1931`,title:`《圣曼努埃尔·布埃诺，殉道者》`,type:`中篇小说`,note:`乡村神父的信仰悖论书写`}],position:`他把存在主义的焦虑写成西班牙语散文与小说，以对话和悖论追问信仰与人格，其思想深度使西班牙现代文学获得哲学性的维度。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-ae8220":{slug:`a-ae8220`,birthDeath:`1888.06.13 — 1935.11.30`,nationality:`葡萄牙`,englishName:`FERNANDO PESSOA`,movement:[`现代主义`,`异名写作`],bio:[`生于里斯本，父亲早逝后随母移居南非，英语教育背景使他早年用英语写诗。回国后任商业翻译，终生低调，生前仅出版一部葡萄牙语诗集。`,`他创造了卡埃罗、坎波斯、雷斯等异名者，各自拥有独立生平、诗学与风格，以多人格写作拆解作者概念，成为现代文学中最彻底的身份实验。`,`《使命》以民族史诗与隐逸主义写葡萄牙的命运；去世后从木箱中整理出两万余页手稿，《不安之书》以半异名者索阿雷斯的片段写都市内省。`],controversies:[],works:[{year:`1925`,title:`《牧羊人》`,type:`长诗`,note:`卡埃罗异名下的自然感知`},{year:`1934`,title:`《使命》`,type:`诗集`,note:`民族史诗与隐逸主义诗篇`},{year:`1942`,title:`《诗歌集》`,type:`诗集`,note:`异名者诗作的集中呈现`},{year:`1982`,title:`《不安之书》`,type:`散文集`,note:`片段体与都市内省思辨`}],position:`他以异名写作把作者拆成多重声音，使身份、真实与虚构在文本中互相渗透，其生前寂寞的手稿成为二十世纪现代主义最具颠覆性的遗产之一。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-492319":{slug:`a-492319`,birthDeath:`1859.08.04 — 1952.02.19`,nationality:`挪威`,englishName:`KNUT HAMSUN`,movement:[`现代主义`,`新浪漫主义`],bio:[`生于挪威贫苦农家，少年做工，两度赴美做农活与电车工。饥饿与流浪的亲身体验，使他的第一部成名作《饥饿》具有近乎临床的精确与幻觉。`,`《饥饿》以第一人称写都市文人的饥饿、羞耻与臆想，打破社会小说的外部描写，被视为现代心理小说的先驱；《神秘》《潘》继续写自然与非理性。`,`《大地的成长》以农耕拓荒的理想化田园史诗获诺贝尔奖；晚年公开支持纳粹，战后受审并罚款，其文学地位与政治污点长期并存，评价分裂。`],controversies:[{tag:`亲纳粹立场`,content:`二战期间公开支持德国占领与纳粹意识形态，战后以叛国罪受审，因年龄与精神状态免于监禁但被罚款，成为北欧文学最具争议的政治污点。`}],works:[{year:`1890`,title:`《饥饿》`,type:`长篇小说`,note:`都市饥饿与幻觉独白叙事`},{year:`1892`,title:`《神秘》`,type:`长篇小说`,note:`小镇陌生人与非理性叙事`},{year:`1894`,title:`《潘》`,type:`长篇小说`,note:`自然、欲望与文明冲突`},{year:`1917`,title:`《大地的成长》`,type:`长篇小说`,note:`拓荒农耕的田园史诗叙事`}],position:`他以《饥饿》开创了以内心幻觉组织叙事的道路，把现代都市的羞耻与欲望写得近乎生理，其心理小说技法影响了欧洲现代主义的一整代作家。`,positionSource:`— 《西方正典》`,nobelYear:1920},"a-9bf9c0":{slug:`a-9bf9c0`,birthDeath:`1882.05.20 — 1949.06.10`,nationality:`挪威`,englishName:`SIGRID UNDSET`,movement:[`现实主义`,`历史小说`],bio:[`生于丹麦凯隆堡，父亲是考古学家，家庭环境培养了她对中世纪历史的兴趣。早期小说《珍妮》写女性的爱情与职业困境，因直白处理性心理引发争议。`,`皈依天主教后，她以中世纪挪威为背景写作《克里斯汀·拉夫朗的女儿》三部曲，以细致的日常、宗教与家族关系重建十四世纪北欧生活，获诺贝尔奖。`,`《奥拉夫·奥敦松》继续写中世纪权力与信仰；纳粹占领挪威后流亡美国，公开反对极权，战后回国继续写作，其历史小说因此获得广泛读者。`],controversies:[],works:[{year:`1911`,title:`《珍妮》`,type:`长篇小说`,note:`女性爱情与职业困境叙事`},{year:`1920`,title:`《花冠》`,type:`长篇小说`,note:`克里斯汀三部曲第一部`},{year:`1922`,title:`《主妇》`,type:`长篇小说`,note:`婚姻、信仰与家族责任`},{year:`1922`,title:`《十字架》`,type:`长篇小说`,note:`三部曲终章与救赎主题`},{year:`1927`,title:`《奥拉夫·奥敦松》`,type:`长篇小说`,note:`中世纪权力与信仰图景`}],position:`她把历史小说从浪漫传奇提升为对信仰、家族与女性命运的严肃勘察，以考古般的细节重建中世纪北欧，使挪威文学获得世界性的历史叙事。`,positionSource:`— 《西方正典》`,nobelYear:1928},"a-a51c12":{slug:`a-a51c12`,birthDeath:`1920.11.23 — 1970.04.20`,nationality:`罗马尼亚裔法国`,englishName:`PAUL CELAN`,movement:[`现代主义`,`大屠杀诗歌`],bio:[`生于切尔诺维茨讲德语的犹太家庭，父母死于纳粹集中营，本人被囚于劳动营。战后流亡布加勒斯特、维也纳，最终定居巴黎，以德语写作。`,`《罂粟与记忆》收录《死亡赋格》，以音乐性的重复与灰烬意象写大屠杀，引发德国文坛震动；此后诗风日趋紧缩，词句断裂，走向沉默的边缘。`,`《从门槛到门槛》《语言栅栏》《无人的玫瑰》把语言本身作为追问对象，晚期《逼迫之光》更趋晦暗；一九七〇年在塞纳河投水自尽。`],controversies:[{tag:`抄袭指控`,content:`一九六〇年代被指抄袭已故诗人戈尔的作品，虽经澄清仍造成严重精神打击，成为其后期孤绝与创作危机的重要背景。`},{tag:`与海德格尔的关系`,content:`一九六七年赴弗赖堡朗诵时，因海德格尔在场及战后德国对纳粹历史的暧昧态度感到受辱，这场风波折射其与大屠杀记忆的持续冲突。`}],works:[{year:`1952`,title:`《罂粟与记忆》`,type:`诗集`,note:`死亡赋格与灰烬意象诗篇`},{year:`1955`,title:`《从门槛到门槛》`,type:`诗集`,note:`门槛、流亡与语言之问`},{year:`1959`,title:`《语言栅栏》`,type:`诗集`,note:`词句断裂与沉默边缘诗篇`},{year:`1963`,title:`《无人的玫瑰》`,type:`诗集`,note:`晚期紧缩的哀歌体诗作`},{year:`1970`,title:`《逼迫之光》`,type:`诗集`,note:`终卷的晦暗与告别之诗`}],position:`他把大屠杀经验压缩为极少的词与断裂的节奏，使德语诗歌在见证的极限处重新寻找语言，其晚期诗学成为战后欧洲最沉重的诗歌遗产。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-e26248":{slug:`a-e26248`,birthDeath:`1897.09.25 — 1962.07.06`,nationality:`美国`,englishName:`WILLIAM FAULKNER`,movement:[`现代主义`,`意识流`,`南方文学`],bio:[`生于密西西比州牛津镇，出身没落的南方家族，一战时在加拿大皇家空军受训但未参战。战后做过书店店员、记者，并短期混迹好莱坞编剧。`,`他以虚构的约克纳帕塔法县为中心写南方历史与家族衰败，《喧哗与骚动》用四个视角与时间错位写康普生家，《我弥留之际》以十五段独白写送葬之旅。`,`《八月之光》《押沙龙，押沙龙！》把种族、乱伦与历史罪责织入繁复句法；一九四九年获诺贝尔奖，晚年成为美国南方神话的缔造者与公共代言人。`],controversies:[],works:[{year:`1926`,title:`《士兵的报酬》`,type:`长篇小说`,note:`战后归乡与疏离的书写`},{year:`1929`,title:`《喧哗与骚动》`,type:`长篇小说`,note:`四重视角与时间错位叙事`},{year:`1930`,title:`《我弥留之际》`,type:`长篇小说`,note:`十五段独白与送葬之旅`},{year:`1932`,title:`《八月之光》`,type:`长篇小说`,note:`种族身份与南方暴力叙事`},{year:`1936`,title:`《押沙龙，押沙龙！》`,type:`长篇小说`,note:`家族史诗与历史罪责叙事`},{year:`1942`,title:`《去吧，摩西》`,type:`短篇集`,note:`林地、血缘与土地占有`}],position:`他以约克纳帕塔法世系把美国南方写成一部关于种族、家族与历史罪责的现代史诗，其意识流与多视角叙事将地域经验提升为普遍的人类寓言。`,positionSource:`— 《西方正典》`,nobelYear:1949},"a-5d4643":{slug:`a-5d4643`,birthDeath:`1899.07.21 — 1961.07.02`,nationality:`美国`,englishName:`ERNEST HEMINGWAY`,movement:[`现代主义`,`迷惘的一代`],bio:[`生于伊利诺伊州橡树园，高中毕业后任报纸记者，一战中在意大利救护队负伤。战后驻巴黎，在斯泰因与庞德的圈子里开始写作，形成极简的散文风格。`,`《太阳照常升起》写战后一代的漂泊与失能，《永别了，武器》把战争与爱情写成克制的悲剧；他以冰山理论删去解释，只留下动作、对话与感官细节。`,`西班牙内战催生《丧钟为谁而鸣》，战后定居古巴，以《老人与海》重获声誉；晚年抑郁与酗酒加剧，一九六一年自杀身亡，遗稿陆续出版。`],controversies:[{tag:`与菲茨杰拉德的关系`,content:`两人曾是亲密友人，海明威在回忆与书信中多次贬低菲茨杰拉德及其写作，这段友谊的破裂与竞争长期是文学史讨论的话题。`}],works:[{year:`1925`,title:`《在我们的时代》`,type:`短篇集`,note:`极简文体与战争创伤叙事`},{year:`1926`,title:`《太阳照常升起》`,type:`长篇小说`,note:`战后一代的漂泊与失能`},{year:`1929`,title:`《永别了，武器》`,type:`长篇小说`,note:`战争与爱情的克制悲剧`},{year:`1940`,title:`《丧钟为谁而鸣》`,type:`长篇小说`,note:`西班牙内战与牺牲主题`},{year:`1952`,title:`《老人与海》`,type:`中篇小说`,note:`硬汉寓言与尊严的书写`}],position:`他把新闻式的简洁锻造成一种现代文体，以省略与克制写暴力、失败与尊严，其冰山理论影响遍及二十世纪小说与纪实写作。`,positionSource:`— 《西方正典》`,nobelYear:1954},"a-51fa06":{slug:`a-51fa06`,birthDeath:`1896.09.24 — 1940.12.21`,nationality:`美国`,englishName:`F. SCOTT FITZGERALD`,movement:[`现代主义`,`爵士时代`],bio:[`生于明尼苏达州圣保罗，普林斯顿求学期间写剧本，未毕业即参军。一九二〇年《人间天堂》畅销，使他与泽尔达的婚姻成为爵士时代的公众神话。`,`《了不起的盖茨比》以第一人称旁观者写暴发户的痴情与美国梦的幻灭，结构精炼、意象明亮，被视为美国小说最完美的短篇长篇之一。`,`《夜色温柔》写婚姻、酒精与才华的耗损；一九三〇年代因妻子精神崩溃与债务陷于低谷，赴好莱坞写剧本，未完成的《最后的大亨》在身后出版。`],controversies:[{tag:`与海明威的友谊`,content:`两人在巴黎结识并互相影响，海明威后来在回忆中公开贬低其人格与才华，这段由亲近转为疏离的关系长期被文学史反复讨论。`}],works:[{year:`1920`,title:`《人间天堂》`,type:`长篇小说`,note:`爵士时代的青春与消费`},{year:`1922`,title:`《美丽与毁灭》`,type:`长篇小说`,note:`婚姻、财富与自我消耗`},{year:`1925`,title:`《了不起的盖茨比》`,type:`长篇小说`,note:`美国梦与幻灭的完美结构`},{year:`1934`,title:`《夜色温柔》`,type:`长篇小说`,note:`婚姻与才华的缓慢崩解`},{year:`1941`,title:`《最后的大亨》`,type:`长篇小说`,note:`好莱坞未完成的遗稿叙事`}],position:`他以明亮的抒情与冷峻的旁观写爵士时代的繁华与空洞，把美国梦的幻灭凝为少数几个不朽的场景，是二十世纪美国小说最具魅力的文体家之一。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-b784e2":{slug:`a-b784e2`,birthDeath:`1902.02.27 — 1968.12.20`,nationality:`美国`,englishName:`JOHN STEINBECK`,movement:[`现实主义`,`社会小说`],bio:[`生于加州萨利纳斯，斯坦福大学辍学，做过农场工、筑路工与记者。大萧条时期的流动劳工经验，成为他最重要的写作素材与道义立场。`,`《煎饼坪》以蒙特雷贫民区的谐谑写边缘群体，《人鼠之间》以紧凑的悲剧写梦想的脆弱；《愤怒的葡萄》以迁徙公路写破产农民的苦难，引发巨大社会争论。`,`战后《罐头厂街》《伊甸之东》转向群体温情与家族寓言，晚期旅行写作与政治评论增多；一九六二年获诺贝尔奖，评价始终在道义力量与文学技巧之间摆动。`],controversies:[],works:[{year:`1935`,title:`《煎饼坪》`,type:`长篇小说`,note:`贫民区的谐谑与共同体`},{year:`1937`,title:`《人鼠之间》`,type:`中篇小说`,note:`梦想与怜悯的底层悲剧`},{year:`1939`,title:`《愤怒的葡萄》`,type:`长篇小说`,note:`大萧条迁徙与社会抗议`},{year:`1945`,title:`《罐头厂街》`,type:`长篇小说`,note:`边缘群体的温情群像叙事`},{year:`1952`,title:`《伊甸之东》`,type:`长篇小说`,note:`家族史与善恶的现代寓言`}],position:`他把社会现实主义与民间叙事结合，以大萧条的经验写底层的尊严与愤怒，其作品使美国文学重新承担起公共道义的责任。`,positionSource:`— 《西方正典》`,nobelYear:1962},"a-d9d195":{slug:`a-d9d195`,birthDeath:`1873.12.07 — 1947.04.24`,nationality:`美国`,englishName:`WILLA CATHER`,movement:[`现实主义`,`边疆文学`],bio:[`生于弗吉尼亚，九岁迁居内布拉斯加草原，移民社区的生活成为其创作根基。大学毕业后做记者与教师，后定居纽约，以编辑与写作维生。`,`《哦，拓荒者！》《我的安东尼亚》以内布拉斯加移民女性为中心，写土地、劳作与记忆，叙述者常为怀旧的旁观者，语调克制而饱含敬意。`,`《我们的一员》《大主教之死》分别写一战与西南部传教史，晚期作品转向天主教信仰与艺术家的孤独，其文体以清澈与节制的笔法著称。`],controversies:[],works:[{year:`1913`,title:`《哦，拓荒者！》`,type:`长篇小说`,note:`草原移民与女性坚韧叙事`},{year:`1915`,title:`《云雀之歌》`,type:`长篇小说`,note:`西部少女与艺术抱负叙事`},{year:`1918`,title:`《我的安东尼亚》`,type:`长篇小说`,note:`移民女性与土地记忆叙事`},{year:`1922`,title:`《我们的一员》`,type:`长篇小说`,note:`一战、农场与失落的记忆`},{year:`1927`,title:`《大主教之死》`,type:`长篇小说`,note:`西南传教史与信仰图景`}],position:`她把美国边疆与移民经验写成关于劳作、土地与记忆的庄严叙事，以克制的抒情抵抗现代性的喧哗，为美国文学提供了少见的女性史诗视角。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-b6e537":{slug:`a-b6e537`,birthDeath:`1862.01.24 — 1937.08.11`,nationality:`美国`,englishName:`EDITH WHARTON`,movement:[`现实主义`,`风俗小说`],bio:[`生于纽约老派上流社会，受私人教育，广泛阅读欧洲文学。一九〇〇年代开始严肃写作，以熟悉的老纽约礼俗为素材，揭示其中的压抑与伪善。`,`《欢乐之家》以社交名媛的坠落写阶层规则，《伊坦·弗洛美》以新英格兰雪村写无望的婚姻；《纯真年代》以一八七〇年代纽约写被礼俗扼杀的爱情，获普利策奖。`,`一战期间定居巴黎并组织救援，战后写《哈德逊河畔的房子》等晚期小说，笔调更冷峻，持续解剖财富、婚姻与女性选择的结构性限制。`],controversies:[],works:[{year:`1905`,title:`《欢乐之家》`,type:`长篇小说`,note:`社交名媛的坠落与礼俗`},{year:`1911`,title:`《伊坦·弗洛美》`,type:`中篇小说`,note:`雪村婚姻与无望之爱叙事`},{year:`1917`,title:`《夏天》`,type:`中篇小说`,note:`乡村少女与欲望觉醒叙事`},{year:`1920`,title:`《纯真年代》`,type:`长篇小说`,note:`老纽约礼俗与爱情牺牲`},{year:`1929`,title:`《哈德逊河畔的房子》`,type:`长篇小说`,note:`晚期婚姻与财富解剖叙事`}],position:`她以精确的风俗细节与冷静的反讽解剖上流社会的规则，把女性在婚姻市场中的困境写成社会结构的标本，是美国风俗小说的高峰。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-8ce182":{slug:`a-8ce182`,birthDeath:`1899.04.22 — 1977.07.02`,nationality:`俄裔美国`,englishName:`VLADIMIR NABOKOV`,movement:[`现代主义`,`后现代主义`],bio:[`生于圣彼得堡贵族家庭，十月革命后流亡，在剑桥攻读斯拉夫与罗曼语。一九二〇年代以笔名西林在柏林俄侨界写作，一九四〇年移居美国，在康奈尔任教。`,`《斩首之邀》《天赋》以俄语写流亡者的记忆与语言迷宫；移居美国后改用英语，《洛丽塔》以不可靠的叙述者写禁忌之恋，一九五五年在巴黎出版后轰动。`,`《微暗的火》以诗歌与注释构成互文迷宫，《阿达》以家族回忆写时间与欲望；晚期定居瑞士，翻译普希金并持续修订早年的俄语旧作。`],controversies:[{tag:`洛丽塔出版争议`,content:`《洛丽塔》一九五五年由巴黎奥林匹亚出版社印行，因题材敏感在英美多国遭禁，一九五八年美国版出版后引发关于文学与道德界限的长期争论。`}],works:[{year:`1926`,title:`《玛丽》`,type:`长篇小说`,note:`流亡者与初恋情结书写`},{year:`1930`,title:`《防守》`,type:`长篇小说`,note:`棋手天才与疯狂的边界`},{year:`1936`,title:`《斩首之邀》`,type:`长篇小说`,note:`荒诞囚禁与意识迷宫叙事`},{year:`1938`,title:`《天赋》`,type:`长篇小说`,note:`流亡作家的文学成长叙事`},{year:`1955`,title:`《洛丽塔》`,type:`长篇小说`,note:`不可靠叙述与禁忌之恋`},{year:`1962`,title:`《微暗的火》`,type:`长篇小说`,note:`诗歌与注释的互文迷宫`},{year:`1969`,title:`《阿达》`,type:`长篇小说`,note:`家族回忆与时间实验叙事`}],position:`他把流亡经验转化为语言与记忆的迷宫，以不可靠叙述和互文结构把小说变成游戏与形而上的追问，是后现代主义叙事的直接先驱。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-b61c42":{slug:`a-b61c42`,birthDeath:`1913.11.07 — 1960.01.04`,nationality:`法国`,englishName:`ALBERT CAMUS`,movement:[`存在主义`,`荒诞文学`],bio:[`生于法属阿尔及利亚贫民家庭，父亲在一战中阵亡，靠奖学金读完哲学。早年做记者、戏剧活动，地中海的光与贫困构成其作品的基本经验。`,`《局外人》以冷静到冷漠的叙述写默尔索的审判，《西西弗的神话》把荒诞定义为人与世界的断裂，提出在无意义中反抗的姿态，二者构成荒诞时期的代表。`,`《鼠疫》以阿尔及利亚城市寓言写面对灾难的团结与责任，《反抗者》转向对革命暴力的批判；一九六〇年死于车祸，未完成的自传体小说《第一人》身后出版。`],controversies:[{tag:`与萨特决裂`,content:`一九五一年《反抗者》出版后，萨特阵营的评论严厉批评其立场，随后公开论战导致两人决裂，成为战后法国左翼知识分子分裂的标志性事件。`}],works:[{year:`1942`,title:`《局外人》`,type:`长篇小说`,note:`冷漠叙述与荒诞审判叙事`},{year:`1942`,title:`《西西弗的神话》`,type:`哲学随笔`,note:`荒诞哲学与反抗姿态论述`},{year:`1947`,title:`《鼠疫》`,type:`长篇小说`,note:`灾难寓言与团结责任叙事`},{year:`1951`,title:`《反抗者》`,type:`哲学随笔`,note:`对革命暴力的批判思辨`},{year:`1956`,title:`《堕落》`,type:`中篇小说`,note:`独白体与道德自审之书`}],position:`他把荒诞写成现代人的基本处境，又以清醒的反抗拒绝虚无，其简洁冷峻的文体与道德立场使他在战后欧洲获得远超文学的影响。`,positionSource:`— 《西方正典》`,nobelYear:1957},"a-97932b":{slug:`a-97932b`,birthDeath:`1905.06.21 — 1980.04.15`,nationality:`法国`,englishName:`JEAN-PAUL SARTRE`,movement:[`存在主义`,`现象学`],bio:[`生于巴黎，巴黎高等师范学校哲学系出身，留学柏林研习胡塞尔与海德格尔。二战被俘后参与抵抗运动，战后成为法国左翼知识界的核心人物。`,`《恶心》以小说的生理性描写呈现存在的偶然与多余，《存在与虚无》提出存在先于本质与自欺概念；《禁闭》以地狱即他人的台词把哲学搬上舞台。`,`《自由之路》以三部曲写战争与选择，《词语》以童年自传反思写作的使命；他长期介入殖民、越南与一九六八年运动，一九六四年拒绝诺贝尔文学奖。`],controversies:[{tag:`与加缪决裂`,content:`《反抗者》出版后，萨特所属《现代》杂志发表尖锐批评，随后两人公开论战并断交，象征战后法国左翼在革命与伦理之间的分裂。`}],works:[{year:`1938`,title:`《恶心》`,type:`长篇小说`,note:`存在的偶然与生理性厌恶`},{year:`1939`,title:`《墙》`,type:`短篇集`,note:`死亡、选择与荒诞处境`},{year:`1943`,title:`《存在与虚无》`,type:`哲学著作`,note:`自欺、自由与存在先于本质`},{year:`1944`,title:`《禁闭》`,type:`戏剧`,note:`他人即地狱的密室寓言`},{year:`1945`,title:`《自由之路》`,type:`长篇小说`,note:`战争中的选择与介入叙事`},{year:`1964`,title:`《词语》`,type:`自传`,note:`童年阅读与写作使命论述`}],position:`他把现象学转化为大众可感的小说与戏剧，以自由、自欺与介入重新定义知识分子的角色，其思想与行动深刻塑造了战后欧洲的公共文化。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-fb2955":{slug:`a-fb2955`,birthDeath:`1908.01.09 — 1986.04.14`,nationality:`法国`,englishName:`SIMONE DE BEAUVOIR`,movement:[`存在主义`,`女性主义`],bio:[`生于巴黎中产家庭，巴黎高等师范学校哲学教师，与萨特结为终身伴侣并保持开放关系。她以小说、回忆录与哲学写作介入战后法国的思想论争。`,`《女宾》以三角关系写他者与自由；《第二性》提出女人不是天生的而是被造成的，系统分析女性如何被文化建构为第二性，成为女性主义理论的奠基文本。`,`《名士风流》以战后知识分子圈写个人与政治的纠葛，获龚古尔奖；晚期回忆录与《老年》继续以存在主义视角审视年龄、身体与死亡。`],controversies:[{tag:`第二性争议`,content:`《第二性》一九五〇年代被梵蒂冈列入禁书目录，并遭保守舆论攻击，其关于女性处境与身体自主的论述引发持续数十年的公共争论。`}],works:[{year:`1943`,title:`《女宾》`,type:`长篇小说`,note:`三角关系与他者意识叙事`},{year:`1949`,title:`《第二性》`,type:`哲学著作`,note:`女性被建构的社会分析`},{year:`1954`,title:`《名士风流》`,type:`长篇小说`,note:`知识分子圈与政治纠葛`},{year:`1958`,title:`《端方淑女回忆录》`,type:`回忆录`,note:`成长、阅读与自我形成`},{year:`1970`,title:`《老年》`,type:`论著`,note:`年龄、身体与社会排斥`}],position:`她把存在主义自由论推向性别领域，揭示女性处境的社会建构，其理论与文学实践共同奠定二十世纪女性主义的思想基础。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-c7f8f0":{slug:`a-c7f8f0`,birthDeath:`1914.04.04 — 1996.03.03`,nationality:`法国`,englishName:`MARGUERITE DURAS`,movement:[`新小说`,`现代主义`],bio:[`生于法属印度支那嘉定，父亲早逝，母亲在湄公河三角洲办学失败。殖民地童年、贫困与母女关系成为她反复书写的核心经验，这一经验贯穿其一生写作。`,`《抵挡太平洋的堤坝》以母亲筑堤抗海的徒劳写殖民地的绝望；她同时编剧《广岛之恋》，以记忆与对话把电影叙事推向文学化，成为新小说与左岸电影的交汇点。`,`《洛尔·瓦·斯泰因的迷狂》写疯狂与欲望；《情人》以极简、断裂的短句重写少女与中国情人的往事，获龚古尔奖并风靡世界，晚期作品趋于碎片化。`],controversies:[],works:[{year:`1950`,title:`《抵挡太平洋的堤坝》`,type:`长篇小说`,note:`殖民地母亲与徒劳筑堤`},{year:`1960`,title:`《广岛之恋》`,type:`电影剧本`,note:`记忆、战争与跨国之恋`},{year:`1964`,title:`《洛尔·瓦·斯泰因的迷狂》`,type:`长篇小说`,note:`疯狂、欲望与叙述分裂`},{year:`1975`,title:`《印度之歌》`,type:`电影剧本`,note:`殖民地记忆与声音叙事`},{year:`1984`,title:`《情人》`,type:`长篇小说`,note:`湄公河少女与中国情人`},{year:`1991`,title:`《来自中国北方的情人》`,type:`长篇小说`,note:`同一往事的重写与变形`}],position:`她把殖民地的童年创伤写成不断重写的文本，以断裂句法、声音与影像的交叉拓展小说的边界，是法国新小说与女性书写之间最独特的声音。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-0c12d3":{slug:`a-0c12d3`,birthDeath:`1906.04.13 — 1989.12.22`,nationality:`爱尔兰裔法国`,englishName:`SAMUEL BECKETT`,movement:[`现代主义`,`荒诞派戏剧`,`后现代主义`],bio:[`生于都柏林新教家庭，三一学院毕业，后赴巴黎高等师范学校任教，与乔伊斯相识并协助其工作。二战期间参加抵抗组织，战后定居法国。`,`他放弃母语改用法语写作，以减法剔除情节、地点与心理，三部曲《莫洛伊》《马龙之死》《无法称呼的人》让叙述本身成为瓦解的对象。`,`《等待戈多》以两个流浪汉的无尽等待写希望与虚无，一九五三年首演震动剧坛；此后《结局》《克拉普的最后一盘录音带》把极简推向沉默的边缘。`],controversies:[],works:[{year:`1938`,title:`《莫菲》`,type:`长篇小说`,note:`伦敦流浪与自我逃避叙事`},{year:`1951`,title:`《莫洛伊》`,type:`长篇小说`,note:`寻找与叙述的双重瓦解`},{year:`1951`,title:`《马龙之死》`,type:`长篇小说`,note:`临终独白与虚构自我叙事`},{year:`1952`,title:`《等待戈多》`,type:`戏剧`,note:`无尽等待与荒诞处境剧作`},{year:`1953`,title:`《无法称呼的人》`,type:`长篇小说`,note:`叙述主体的彻底消解叙事`},{year:`1958`,title:`《克拉普的最后一盘录音带》`,type:`戏剧`,note:`录音回放与衰老记忆剧作`}],position:`他以减法把小说与戏剧推向沉默的极限，用极少的语言呈现存在的重复与虚无，是荒诞派戏剧与后现代叙事共同的起点性人物。`,positionSource:`— 《西方正典》`,nobelYear:1969},"a-627fdf":{slug:`a-627fdf`,birthDeath:`1903.06.25 — 1950.01.21`,nationality:`英国`,englishName:`GEORGE ORWELL`,movement:[`现实主义`,`政治寓言`],bio:[`生于英属印度，原名埃里克·布莱尔，伊顿公学毕业后任帝国警察驻缅甸，因目睹殖民暴力而辞职。随后在巴黎、伦敦体验贫困，写下纪实处女作。`,`《缅甸岁月》写殖民者的道德堕落，《向加泰罗尼亚致敬》以西班牙内战经历揭露左翼内部清洗；他坚持用平实语言对抗政治修辞的扭曲。`,`《动物农场》以寓言写革命如何蜕变为新专制，《一九八四》构造极权监控与语言控制的完整图景，两者使其成为二十世纪最具影响力的政治作家。`],controversies:[{tag:`名单争议`,content:`一九四九年他应英国外交部情报部门之请，提供一份被怀疑倾向共产主义的文化人名名单，此事在二〇〇三年档案公开后引发对其政治伦理的争论。`}],works:[{year:`1933`,title:`《巴黎伦敦落魄记》`,type:`纪实`,note:`底层贫困的亲历记录论述`},{year:`1934`,title:`《缅甸岁月》`,type:`长篇小说`,note:`殖民者的道德堕落记录`},{year:`1938`,title:`《向加泰罗尼亚致敬》`,type:`纪实`,note:`西班牙内战与左翼清洗`},{year:`1945`,title:`《动物农场》`,type:`中篇小说`,note:`革命蜕变的动物寓言叙事`},{year:`1949`,title:`《一九八四》`,type:`长篇小说`,note:`极权监控与语言控制叙事`}],position:`他把政治观察写成清晰的散文与锋利的寓言，揭示权力如何操纵语言与记忆，其概念如老大哥与双重思想已成为公共政治讨论的通用词汇。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-725f1c":{slug:`a-725f1c`,birthDeath:`1911.09.19 — 1993.06.19`,nationality:`英国`,englishName:`WILLIAM GOLDING`,movement:[`现实主义`,`寓言小说`],bio:[`生于康沃尔，牛津大学学习自然科学后转英国文学，战时在皇家海军服役，参与诺曼底登陆。战后长期在中学任教，同时坚持写作小说。`,`《蝇王》以荒岛上的男童群体写文明秩序的迅速崩解，把人性之恶置于寓言结构之中；《继承者》以尼安德特人视角写暴力与认知的更替。`,`《品彻·马丁》《教堂尖塔》《黑暗昭昭》持续以孤岛、塔楼与封闭空间探讨原罪与救赎；一九八三年获诺贝尔奖，其寓言式写作在战后英国小说中独树一帜。`],controversies:[],works:[{year:`1954`,title:`《蝇王》`,type:`长篇小说`,note:`荒岛童群与文明崩解叙事`},{year:`1955`,title:`《继承者》`,type:`长篇小说`,note:`尼安德特人视角的暴力`},{year:`1956`,title:`《品彻·马丁》`,type:`长篇小说`,note:`海难之后的意识挣扎叙事`},{year:`1964`,title:`《教堂尖塔》`,type:`长篇小说`,note:`信仰偏执与建筑寓言叙事`},{year:`1979`,title:`《黑暗昭昭》`,type:`长篇小说`,note:`善恶对峙的现代寓言叙事`}],position:`他把道德寓言重新带入战后英国小说，以封闭情境检验文明与人性的脆弱，其作品在通俗可读与哲学追问之间保持了罕见的平衡。`,positionSource:`— 《西方正典》`,nobelYear:1983},"a-523128":{slug:`a-523128`,birthDeath:`1891.05.15 — 1940.03.10`,nationality:`俄国`,englishName:`MIKHAIL BULGAKOV`,movement:[`现代主义`,`讽刺文学`,`魔幻现实主义`],bio:[`生于基辅神学院教授家庭，基辅大学医学博士，一战与内战期间行医。弃医从文后以《白卫军》写基辅白军知识分子的溃败，剧作《图尔宾一家的日子》一度轰动。`,`一九二〇年代末作品遭批判禁演，他致信斯大林请求出国或谋职，后在莫斯科艺术剧院任助理导演。此期秘密写作《狗心》《不祥的蛋》等讽刺中篇。`,`《大师和玛格丽特》自一九二八年写到去世，把撒旦造访莫斯科、罗马总督彼拉多与大师的爱情并置，直到一九六六至六七年才被删节发表。`],controversies:[{tag:`作品遭禁`,content:`一九二〇年代末其剧作与小说被批评为敌对意识形态而禁演，他于一九三〇年致信斯大林，此事成为苏联文学审查史的著名案例。`}],works:[{year:`1925`,title:`《白卫军》`,type:`长篇小说`,note:`基辅白军与知识分子溃败`},{year:`1925`,title:`《狗心》`,type:`中篇小说`,note:`器官移植与苏联新人的讽刺`},{year:`1926`,title:`《图尔宾一家的日子》`,type:`戏剧`,note:`改编自白卫军的舞台剧`},{year:`1967`,title:`《大师和玛格丽特》`,type:`长篇小说`,note:`撒旦、彼拉多与爱情叙事`}],position:`他以讽刺、怪诞与宗教寓言对抗苏联官方文学规范，把个人在历史暴力中的处境写成魔幻而悲悯的史诗，其遗作成为二十世纪俄语小说的地下经典。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-f3eb46":{slug:`a-f3eb46`,birthDeath:`1927.10.16 — 2015.04.13`,nationality:`德国`,englishName:`GUNTER GRASS`,movement:[`现代主义`,`魔幻现实主义`,`政治写作`],bio:[`生于但泽自由市，战时入空军辅助队，战后做过石匠、爵士鼓手与雕塑学徒。他参与四七社，以诗歌与剧本起步，并长期介入德国社会政治。`,`《铁皮鼓》以侏儒奥斯卡的视角写但泽从魏玛到战后的历史，用怪诞、鼓声与碎玻璃般的语言打破战后德国的沉默，成为但泽三部曲的开端。`,`《猫与鼠》《狗年月》继续清算纳粹与战后经济奇迹；《比目鱼》《母鼠》转向性别与历史寓言，晚期《蟹行》重写战争逃亡与右翼暴力。`],controversies:[{tag:`党卫军经历`,content:`二〇〇六年他公开承认战时曾加入武装党卫军，此前长期未提及，引发关于其道德权威与迟来坦白的广泛争论。`},{tag:`以色列诗作争议`,content:`二〇一二年发表散文诗批评以色列对伊朗的政策，被指带有反犹暗示，引发德国与以色列舆论的强烈批评。`}],works:[{year:`1959`,title:`《铁皮鼓》`,type:`长篇小说`,note:`侏儒视角与但泽历史叙事`},{year:`1961`,title:`《猫与鼠》`,type:`中篇小说`,note:`青少年记忆与纳粹时代`},{year:`1963`,title:`《狗年月》`,type:`长篇小说`,note:`战后经济奇迹的清算叙事`},{year:`1977`,title:`《比目鱼》`,type:`长篇小说`,note:`性别与历史的厨房寓言`},{year:`2002`,title:`《蟹行》`,type:`中篇小说`,note:`沉船逃亡与右翼回潮叙事`}],position:`他把怪诞叙事与德国历史清算结合，以粗粝的想象力和公共介入把战后德语文学从沉默中拽出，是君特·格拉斯式记忆政治的代名词。`,positionSource:`— 《西方正典》`,nobelYear:1999},"a-b275d3":{slug:`a-b275d3`,birthDeath:`1917.12.21 — 1985.07.16`,nationality:`德国`,englishName:`HEINRICH BOLL`,movement:[`现实主义`,`战后文学`],bio:[`生于科隆天主教家庭，二战中应征入伍，多次负伤并曾被俘。战后回到废墟中的科隆，与四七社交往，以短篇和长篇小说写战争与贫困的延续。`,`《列车正点》《亚当，你到过哪里》以士兵视角写战争的日常性；《一声不吭》以战后夫妻的窘迫写经济奇迹背后的精神空洞，形成其冷静而悲悯的笔调。`,`《九点半的台球》《小丑之见》《女士及众生相》持续批判教会、军国主义与消费社会；一九七二年获诺贝尔奖，同时以人权立场介入国内外政治。`],controversies:[{tag:`与舆论的冲突`,content:`一九七二年就巴德尔与迈因霍夫集团发表评论，被部分媒体指为同情恐怖分子，引发与保守报业的激烈论战。`}],works:[{year:`1949`,title:`《列车正点》`,type:`中篇小说`,note:`战争日常与士兵归乡叙事`},{year:`1951`,title:`《亚当，你到过哪里》`,type:`长篇小说`,note:`战争经验与道德废墟叙事`},{year:`1953`,title:`《一声不吭》`,type:`长篇小说`,note:`战后贫困与婚姻窘迫叙事`},{year:`1959`,title:`《九点半的台球》`,type:`长篇小说`,note:`家族记忆与军国主义叙事`},{year:`1963`,title:`《小丑之见》`,type:`长篇小说`,note:`天主教与消费社会讽刺`},{year:`1971`,title:`《女士及众生相》`,type:`长篇小说`,note:`战后德国的全景群像书写`}],position:`他以清醒的现实主义写战争与战后德国的道德废墟，语言朴素而精确，把社会批判与人间同情并置，是战后德语文学最具公共良知的作家之一。`,positionSource:`— 《西方正典》`,nobelYear:1972},"a-709d82":{slug:`a-709d82`,birthDeath:`1926.06.25 — 1973.10.17`,nationality:`奥地利`,englishName:`INGEBORG BACHMANN`,movement:[`现代主义`,`战后诗歌`],bio:[`生于克拉根福，维也纳大学攻读哲学、德语文学与心理学。一九五三年在四七社朗读会一举成名，随后与策兰相识，这段关系深刻影响其诗与小说。`,`诗集《借来的时间》《大熊的呼唤》以音乐性的自由节奏写流亡、爱情与语言的边界；广播剧《曼哈顿的好上帝》与短篇集《三十岁》拓展其叙事实验。`,`未完成的长篇《马琳娜》以女性叙述者写爱与自我的崩溃，一九七一年出版；她长期依赖药物与酒精，一九七三年在罗马寓所因火灾去世。`],controversies:[],works:[{year:`1953`,title:`《借来的时间》`,type:`诗集`,note:`战后时间感与抒情自我`},{year:`1956`,title:`《大熊的呼唤》`,type:`诗集`,note:`音乐性自由节奏与爱情`},{year:`1961`,title:`《三十岁》`,type:`短篇集`,note:`女性经验与叙事实验叙事`},{year:`1971`,title:`《马琳娜》`,type:`长篇小说`,note:`爱与自我崩溃的独白叙事`}],position:`她把战后德语诗歌推向音乐与沉默的边界，以女性视角写爱情、流亡与语言的失效，其短暂创作成为战后欧洲最重要的诗性声音之一。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-3aa0e4":{slug:`a-3aa0e4`,birthDeath:`1923.10.15 — 1985.09.19`,nationality:`意大利`,englishName:`ITALO CALVINO`,movement:[`后现代主义`,`幻想文学`],bio:[`生于古巴圣地亚哥，父母是植物学家，童年在意大利圣雷莫度过。二战参加抵抗运动，战后加入共产党，以新现实主义长篇《通向蜘蛛巢的小径》起步。`,`一九五〇年代转向幻想与寓言，《分成两半的子爵》《树上的男爵》《不存在的骑士》以历史寓言写完整与分裂；同时整理意大利童话，深化其对民间叙事的兴趣。`,`移居巴黎后与结构主义圈子交往，《宇宙奇趣》《看不见的城市》《如果在冬夜，一个旅人》把科学与文学、城市想象与阅读行为变成小说结构本身。`],controversies:[],works:[{year:`1947`,title:`《通向蜘蛛巢的小径》`,type:`长篇小说`,note:`抵抗运动与新现实主义`},{year:`1952`,title:`《分成两半的子爵》`,type:`中篇小说`,note:`分裂自我与历史寓言叙事`},{year:`1957`,title:`《树上的男爵》`,type:`长篇小说`,note:`拒绝地面的启蒙寓言叙事`},{year:`1965`,title:`《宇宙奇趣》`,type:`短篇集`,note:`科学与神话的轻逸融合`},{year:`1972`,title:`《看不见的城市》`,type:`长篇小说`,note:`城市想象与叙述框架叙事`},{year:`1979`,title:`《如果在冬夜，一个旅人》`,type:`长篇小说`,note:`阅读行为成为小说结构`},{year:`1983`,title:`《帕洛马尔》`,type:`长篇小说`,note:`观察、沉默与认知极限`}],position:`他把幻想、科学与叙事学熔为一体，以轻逸的想象力处理沉重的现代经验，其小说不断追问阅读与写作本身，是后现代文学最优雅的实践者。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-9abab7":{slug:`a-9abab7`,birthDeath:`1932.01.05 — 2016.02.19`,nationality:`意大利`,englishName:`UMBERTO ECO`,movement:[`后现代主义`,`符号学小说`],bio:[`生于皮埃蒙特亚历山德里亚，都灵大学法学出身，长期任博洛尼亚大学符号学教授。他研究中世纪美学、大众文化与传播理论，是欧洲最具公共影响力的学者之一。`,`《开放的作品》提出文本的多义与读者参与，《读者的角色》推动接受理论；他为报刊撰写大量文化评论，把符号学带入日常生活的分析。`,`四十八岁转向小说，《玫瑰之名》以中世纪修道院谋杀案包裹符号学与信仰之争，成为全球畅销书；《傅科摆》《昨日之岛》《波多里诺》继续以历史与伪史编织观念悬疑。`],controversies:[],works:[{year:`1962`,title:`《开放的作品》`,type:`论著`,note:`文本多义与读者参与论述`},{year:`1979`,title:`《读者的角色》`,type:`论著`,note:`接受理论与阅读实践论述`},{year:`1980`,title:`《玫瑰之名》`,type:`长篇小说`,note:`修道院谋杀与符号迷宫`},{year:`1988`,title:`《傅科摆》`,type:`长篇小说`,note:`秘术、阴谋与解释狂叙事`},{year:`1994`,title:`《昨日之岛》`,type:`长篇小说`,note:`十七世纪与虚构地图叙事`},{year:`2000`,title:`《波多里诺》`,type:`长篇小说`,note:`谎言、圣物与历史伪造`}],position:`他把符号学理论转化为引人入胜的历史悬疑，让学术概念进入大众阅读，其小说既是观念的迷宫也是关于解释本身的寓言，打通了精英与通俗的界限。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-e26e08":{slug:`a-e26e08`,birthDeath:`1919.07.31 — 1987.04.11`,nationality:`意大利`,englishName:`PRIMO LEVI`,movement:[`见证文学`,`现实主义`],bio:[`生于都灵犹太家庭，化学博士，一九四四年被押往奥斯维辛，因化学专业被分配到工厂实验室而幸存。战后返乡，从事工业化学工作并开始写作。`,`《这是不是个人》以冷静到近乎科学的观察写集中营如何摧毁人的尊严，坚持不把受害者神圣化；《休战》写解放后漫长的返乡旅程与幸存者的错位。`,`《元素周期表》以化学元素串联二十一个片段，把职业与生命史写成隐喻；《被淹没和被拯救的》系统反思集中营的灰色地带与记忆的不可靠。`],controversies:[{tag:`死亡性质争论`,content:`一九八七年他从公寓楼梯坠落身亡，官方判定为自杀，但部分研究者与友人认为可能是意外，围绕其晚年抑郁与死亡性质的争论持续至今。`}],works:[{year:`1947`,title:`《这是不是个人》`,type:`回忆录`,note:`集中营中的尊严与瓦解`},{year:`1963`,title:`《休战》`,type:`回忆录`,note:`解放后返乡与幸存者错位`},{year:`1975`,title:`《元素周期表》`,type:`短篇集`,note:`以化学元素串联生命史`},{year:`1982`,title:`《若非现在，何时》`,type:`长篇小说`,note:`抵抗运动与游击记忆叙事`},{year:`1986`,title:`《被淹没和被拯救的》`,type:`论著`,note:`灰色地带与记忆反思论述`}],position:`他以化学家的精确与证人的克制写大屠杀，拒绝煽情与英雄化，把见证提升为关于人性灰区的伦理分析，是二十世纪见证文学最不可替代的声音。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-137317":{slug:`a-137317`,birthDeath:`1929.04.01 — 2023.07.11`,nationality:`捷克裔法国`,englishName:`MILAN KUNDERA`,movement:[`现代主义`,`后现代主义`],bio:[`生于捷克斯洛伐克布尔诺，父亲是钢琴家，自幼学习音乐，后入布拉格电影学院任教。音乐结构对其小说章法与节奏影响极深，他常以复调与变奏组织叙事。`,`《玩笑》以个人被政治玩笑毁掉的一生写集体狂热；《生活在他方》写诗人的成长与抒情幻象；一九六八年之后作品被禁，一九七五年流亡法国。`,`《笑忘录》《不能承受的生命之轻》把政治、性与哲学随笔熔为一体，以轻与重、遗忘与记忆的辩证写个人在历史中的处境，晚期转向法语写作与小说美学随笔。`],controversies:[{tag:`举报者争议`,content:`二〇〇八年捷克杂志披露他一九五〇年曾向警方举报一名为西方情报机构工作的同学，昆德拉本人否认相关指控，此事在捷克与法国引发长期争论。`}],works:[{year:`1967`,title:`《玩笑》`,type:`长篇小说`,note:`政治玩笑与个人毁灭叙事`},{year:`1969`,title:`《生活在他方》`,type:`长篇小说`,note:`诗人成长与抒情幻象叙事`},{year:`1979`,title:`《笑忘录》`,type:`长篇小说`,note:`遗忘、笑声与政治记忆`},{year:`1984`,title:`《不能承受的生命之轻》`,type:`长篇小说`,note:`轻与重、偶然与选择叙事`},{year:`1990`,title:`《不朽》`,type:`长篇小说`,note:`形象、自我与欧洲文化`}],position:`他把小说视为存在的勘探，以音乐式结构与哲学随笔扩展叙事边界，用反讽处理政治与私人生活，使中欧经验进入世界文学的普遍讨论。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-4b072a":{slug:`a-4b072a`,birthDeath:`1931.02.18 — 2019.08.05`,nationality:`美国`,englishName:`TONI MORRISON`,movement:[`后现代主义`,`非裔美国文学`],bio:[`生于俄亥俄州洛兰，原名克洛·安东尼·沃福德，霍华德大学与康奈尔大学出身，硕士论文研究福克纳与伍尔夫。长期在兰登书屋任编辑，扶植非裔作家。`,`《最蓝的眼睛》以少女的自我厌恶写种族审美暴力，《秀拉》以两个女性的友谊写社区规则；《所罗门之歌》以寻宝与家族传说写非裔历史记忆。`,`《宠儿》以杀婴与还魂写奴隶制的创伤，获普利策奖；《爵士》《天堂》以音乐结构与社区史继续实验，一九九三年成为首位获诺贝尔文学奖的非裔美国女性。`],controversies:[],works:[{year:`1970`,title:`《最蓝的眼睛》`,type:`长篇小说`,note:`种族审美与少女自我厌恶`},{year:`1973`,title:`《秀拉》`,type:`长篇小说`,note:`女性友谊与社区规则叙事`},{year:`1977`,title:`《所罗门之歌》`,type:`长篇小说`,note:`家族传说与飞行记忆叙事`},{year:`1981`,title:`《焦油娃娃》`,type:`长篇小说`,note:`欲望、阶级与黑人身份`},{year:`1987`,title:`《宠儿》`,type:`长篇小说`,note:`奴隶制创伤与还魂叙事`},{year:`1992`,title:`《爵士》`,type:`长篇小说`,note:`哈莱姆与爵士乐结构叙事`}],position:`她把非裔美国人的历史创伤写成具有神话密度的文学，以多重叙述、音乐结构与魔幻元素重构记忆，使被压抑的族群经验进入正典核心。`,positionSource:`— 《西方正典》`,nobelYear:1993},"a-c46403":{slug:`a-c46403`,birthDeath:`1913.03.01 — 1994.04.16`,nationality:`美国`,englishName:`RALPH ELLISON`,movement:[`现代主义`,`非裔美国文学`],bio:[`生于俄克拉何马城，父早逝，靠奖学金入塔斯基吉学院学习音乐，后赴纽约，与理查德·赖特相识并开始写作。爵士乐与小号经验影响其句法与节奏感。`,`《看不见的人》历时七年写成，以无名叙述者的地下独白写种族的不可见性，融合艾略特、乔伊斯与黑人音乐传统，一九五二年出版即获国家图书奖。`,`此后他主要写随笔与演讲，《影子与行动》讨论种族、文化与作家责任；长篇遗作《六月庆典》在身后出版，其未完成状态也印证他对形式的苛求。`],controversies:[],works:[{year:`1952`,title:`《看不见的人》`,type:`长篇小说`,note:`无名叙述者与种族不可见`},{year:`1964`,title:`《影子与行动》`,type:`随笔集`,note:`种族、文化与作家责任`},{year:`1999`,title:`《六月庆典》`,type:`长篇小说`,note:`身后出版的未完成遗作`}],position:`他以一部小说确立非裔美国现代主义的标高，把种族经验写成关于身份与可见性的普遍寓言，其音乐性句法与反讽结构影响此后数代作家。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-17f184":{slug:`a-17f184`,birthDeath:`1924.08.02 — 1987.12.01`,nationality:`美国`,englishName:`JAMES BALDWIN`,movement:[`现实主义`,`非裔美国文学`],bio:[`生于哈莱姆贫民区，继父是浸信会牧师，十四岁开始讲道，三年后离开教会。教堂的语言训练塑造了他后来散文的节奏与先知式的语调。`,`《向苍天呼吁》以继父家庭的自传材料写宗教与种族，《乔瓦尼的房间》以巴黎同性恋情写欲望与羞耻；他移居法国，以局外人视角审视美国。`,`《下一次将是烈火》以书信与随笔写种族愤怒与道德清算，《另一个国家》处理跨种族与性取向的复杂关系，他成为民权运动中最具文学力量的公共声音之一。`],controversies:[],works:[{year:`1953`,title:`《向苍天呼吁》`,type:`长篇小说`,note:`哈莱姆宗教与家庭创伤`},{year:`1955`,title:`《土生子札记》`,type:`随笔集`,note:`种族经验与自我审视论述`},{year:`1956`,title:`《乔瓦尼的房间》`,type:`长篇小说`,note:`巴黎同性爱与羞耻书写`},{year:`1962`,title:`《另一个国家》`,type:`长篇小说`,note:`跨种族与性取向纠葛叙事`},{year:`1963`,title:`《下一次将是烈火》`,type:`随笔集`,note:`种族愤怒与道德清算论述`},{year:`1968`,title:`《告诉我火车开走多久了》`,type:`长篇小说`,note:`美国种族与历史记忆叙事`}],position:`他把布道式的修辞与小说心理深度结合，以毫不妥协的诚实写种族、性与信仰，其散文成为美国公共讨论中道德良知的标杆。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-94e0b3":{slug:`a-94e0b3`,birthDeath:`1940.05.24 — 1996.01.28`,nationality:`俄裔美国`,englishName:`JOSEPH BRODSKY`,movement:[`现代主义`,`流亡诗歌`],bio:[`生于列宁格勒犹太家庭，少年辍学，做过车间工、船工与地质勘探队员。自学英语与波兰语，受阿赫玛托娃提携，成为列宁格勒地下诗歌圈的核心成员。`,`一九六四年以社会寄生虫罪名受审并被流放北方劳改营，这段经历成为其诗歌与散文的重要背景；一九七二年被驱逐出境，后定居美国并在大学任教。`,`他以俄语写诗、以英语写散文，《话语的一部分》《罗马哀歌》在古典格律与现代断裂之间建立个人声调；一九八七年获诺贝尔奖，晚年推动诗歌教育。`],controversies:[],works:[{year:`1965`,title:`《短诗与长诗》`,type:`诗集`,note:`早期地下诗歌与流放诗篇`},{year:`1970`,title:`《在荒野中停留》`,type:`诗集`,note:`北方流放与时间主题诗篇`},{year:`1977`,title:`《话语的一部分》`,type:`诗集`,note:`流亡、语言与古典格律`},{year:`1992`,title:`《水印》`,type:`散文`,note:`威尼斯与冬天的抒情散文`},{year:`1995`,title:`《悲伤与理智》`,type:`随笔集`,note:`诗歌、流亡与文明思辨`}],position:`他继承俄国诗歌的古典格律与形而上学传统，以流亡者的位置写语言、记忆与文明，其诗与散文共同构成二十世纪后半期最重要的跨语写作之一。`,positionSource:`— 《西方正典》`,nobelYear:1987},"a-98eb45":{slug:`a-98eb45`,birthDeath:`1915.06.10 — 2005.04.05`,nationality:`美国`,englishName:`SAUL BELLOW`,movement:[`现实主义`,`知识分子小说`],bio:[`生于加拿大魁北克拉钦，九岁迁居芝加哥犹太移民区，家庭语言混杂。芝加哥大学与西北大学人类学出身，任教多年，同时为《党派评论》等刊物写作。`,`《晃来晃去的人》《受害者》写战后犹太人的道德焦虑；《奥吉·马奇历险记》以流浪汉体写自我塑造，《雨王汉德森》以非洲之旅写精神饥渴。`,`《赫索格》以大量未寄出的书信写知识分子的崩溃与自嘲，《洪堡的礼物》对照诗人与成功作家的命运；一九七六年获诺贝尔奖，晚期《拉维尔斯坦》再引争议。`],controversies:[],works:[{year:`1944`,title:`《晃来晃去的人》`,type:`长篇小说`,note:`战后等待与存在焦虑叙事`},{year:`1947`,title:`《受害者》`,type:`长篇小说`,note:`犹太身份与道德纠缠叙事`},{year:`1953`,title:`《奥吉·马奇历险记》`,type:`长篇小说`,note:`流浪汉体与自我塑造叙事`},{year:`1959`,title:`《雨王汉德森》`,type:`长篇小说`,note:`非洲之旅与精神饥渴叙事`},{year:`1964`,title:`《赫索格》`,type:`长篇小说`,note:`未寄书信与知识分子崩溃`},{year:`1975`,title:`《洪堡的礼物》`,type:`长篇小说`,note:`诗人与作家的命运对照`}],position:`他把欧洲思想小说传统移植到美国都市经验，以喜剧性的夸张与内省写知识分子的精神困境，使犹太移民经验成为美国文学的正典主题。`,positionSource:`— 《西方正典》`,nobelYear:1976},"a-0f5946":{slug:`a-0f5946`,birthDeath:`1932.03.18 — 2009.01.27`,nationality:`美国`,englishName:`JOHN UPDIKE`,movement:[`现实主义`,`后现代现实主义`],bio:[`生于宾夕法尼亚州希灵顿，哈佛大学毕业后在牛津学习一年，随即进入《纽约客》任编辑与撰稿人。他长期为该刊写短篇、诗歌与评论，产量极高。`,`《兔子，跑吧》以哈利·安格斯特罗姆的逃离写战后美国中产的窒息，此后每十年一部的兔子系列追踪其婚姻、工作与衰老，构成一部编年史。`,`《半人马》《夫妇》《伊甸之东》等写小镇教师、婚姻危机与宗教怀疑；他以细密到近乎显微镜式的描写著称，晚期作品转向记忆、死亡与伊斯兰文化。`],controversies:[],works:[{year:`1960`,title:`《兔子，跑吧》`,type:`长篇小说`,note:`中产窒息与逃离的书写`},{year:`1963`,title:`《半人马》`,type:`长篇小说`,note:`小镇教师与神话对照叙事`},{year:`1968`,title:`《夫妇》`,type:`长篇小说`,note:`婚姻、通奸与郊区生活`},{year:`1971`,title:`《兔子归来》`,type:`长篇小说`,note:`六十年代与中产困境叙事`},{year:`1981`,title:`《兔子富了》`,type:`长篇小说`,note:`消费社会与中年成功叙事`},{year:`1990`,title:`《兔子歇了》`,type:`长篇小说`,note:`衰老、死亡与时代终结`}],position:`他以极高的密度记录美国中产阶级的日常生活，把性、宗教与死亡写成可触的细节，兔子四部曲成为战后美国社会最完整的文学编年史之一。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-7bed5a":{slug:`a-7bed5a`,birthDeath:`1911.03.26 — 1983.02.25`,nationality:`美国`,englishName:`TENNESSEE WILLIAMS`,movement:[`现代主义`,`南方戏剧`],bio:[`生于密西西比州哥伦布，父亲是推销员，家庭关系紧张，妹妹的精神疾病与母亲的压抑成为其剧作反复出现的素材。他漂泊多城，做过各种零工并持续写作。`,`《玻璃动物园》以记忆剧的形式让劳拉与阿曼达在烛光中重现往事，一举成名；《欲望号街车》以布兰奇与斯坦利的冲突写南方旧秩序的性暴力崩解，获普利策奖。`,`《热铁皮屋顶上的猫》以家族谎言与欲望写田纳西三角洲，《甜蜜的青春鸟》《蜥蜴的夜晚》转向晚期更阴郁的题材；晚年依赖药物与酒精，死于旅馆。`],controversies:[],works:[{year:`1944`,title:`《玻璃动物园》`,type:`戏剧`,note:`记忆剧与南方家庭幻象`},{year:`1947`,title:`《欲望号街车》`,type:`戏剧`,note:`南方旧秩序与性暴力剧作`},{year:`1950`,title:`《玫瑰纹身》`,type:`戏剧`,note:`寡妇、欲望与西西里社区`},{year:`1955`,title:`《热铁皮屋顶上的猫》`,type:`戏剧`,note:`家族谎言与欲望的舞台`},{year:`1959`,title:`《甜蜜的青春鸟》`,type:`戏剧`,note:`青春、衰败与救赎幻象`},{year:`1961`,title:`《蜥蜴的夜晚》`,type:`戏剧`,note:`晚期宗教焦虑与暴力剧作`}],position:`他把南方哥特、心理现实主义与诗性对话结合，以欲望与幻象写失败者的尊严，扩大了美国戏剧对性、疯狂与家庭暴力的表现尺度。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-7f8ca1":{slug:`a-7f8ca1`,birthDeath:`1915.10.17 — 2005.02.10`,nationality:`美国`,englishName:`ARTHUR MILLER`,movement:[`现实主义`,`社会戏剧`],bio:[`生于纽约哈莱姆犹太移民家庭，父亲在股市崩盘中破产，少年时送面包补贴家用。密歇根大学求学期间开始写剧，战后以《全是我的儿子》确立声名。`,`《推销员之死》以威利·洛曼的回忆与幻觉交织写美国梦的破产，舞台时间与心理时间重叠，成为美国悲剧的现代范本，并获普利策奖。`,`《萨勒姆的女巫》以十七世纪猎巫影射麦卡锡主义，《桥头眺望》以移民码头工人写尊严与背叛；他本人曾拒绝对非美活动委员会供出他人而被判藐视国会。`],controversies:[{tag:`藐视国会`,content:`一九五六年他拒绝向众议院非美活动调查委员会供出他人姓名，因此被判藐视国会，判决后来被推翻，此事成为麦卡锡时期知识界的标志性抵抗。`}],works:[{year:`1947`,title:`《全是我的儿子》`,type:`戏剧`,note:`战争牟利与家庭罪责剧作`},{year:`1949`,title:`《推销员之死》`,type:`戏剧`,note:`美国梦破产的现代悲剧`},{year:`1953`,title:`《萨勒姆的女巫》`,type:`戏剧`,note:`猎巫寓言与麦卡锡主义`},{year:`1955`,title:`《桥头眺望》`,type:`戏剧`,note:`码头移民与尊严背叛剧作`},{year:`1964`,title:`《堕落之后》`,type:`戏剧`,note:`自传性记忆与道德审判`}],position:`他把社会批判与家庭悲剧紧密结合，以普通人的失败质问美国梦的承诺，其剧作在商业舞台与政治反思之间确立了美国严肃戏剧的公共性。`,positionSource:`— 《西方正典》`,nobelYear:null},"a-fd3fd4":{slug:`a-fd3fd4`,birthDeath:`1856.07.26 — 1950.11.02`,nationality:`爱尔兰裔英国`,englishName:`GEORGE BERNARD SHAW`,movement:[`现实主义`,`社会问题剧`],bio:[`生于都柏林新教家庭，二十岁赴伦敦，早年写小说失败，转而写音乐与戏剧评论。加入费边社后成为渐进社会主义的代言人，以演说与小册子介入公共论争。`,`他以《华伦夫人的职业》《芭芭拉少校》《皮格马利翁》等剧把婚姻、卖淫、军火与阶级问题搬上舞台，用机智对白与观念冲突取代情节剧，推动英国戏剧现代化。`,`《人与超人》《圣女贞德》把哲学辩论与历史人物写入戏剧，一九二五年获诺贝尔奖；晚年仍写作政治剧与书信，其论战式文体影响深远。`],controversies:[{tag:`对苏联的辩护`,content:`一九三〇年代访问苏联后公开为其制度辩护，并对斯大林时期的镇压轻描淡写，这一立场长期受到批评，与其费边式渐进主义形成张力。`}],works:[{year:`1893`,title:`《华伦夫人的职业》`,type:`戏剧`,note:`卖淫经济与体面社会剧作`},{year:`1894`,title:`《康蒂妲》`,type:`戏剧`,note:`婚姻、信仰与女性选择`},{year:`1898`,title:`《凯撒与克莉奥佩特拉》`,type:`戏剧`,note:`历史人物与政治机智剧作`},{year:`1902`,title:`《人与超人》`,type:`戏剧`,note:`生命哲学与观念辩论剧作`},{year:`1905`,title:`《芭芭拉少校》`,type:`戏剧`,note:`军火资本与救世军的对峙`},{year:`1912`,title:`《皮格马利翁》`,type:`戏剧`,note:`语言、阶级与身份塑造`},{year:`1923`,title:`《圣女贞德》`,type:`戏剧`,note:`历史信仰与权力审判剧作`}],position:`他以机智的辩论剧把社会问题变成舞台娱乐，用观念冲突取代情节煽情，为现代英语戏剧确立了智性与公共关怀并重的传统。`,positionSource:`— 《西方正典》`,nobelYear:1925}};export{e as g4};